package com.example

import com.example.ExamQuestionHelper.QSpec

/**
 * Curated Geography Live Exam Hall Bank — Domain 6:
 * ස්වාභාවික සම්පත්, බලශක්ති හා ජල සම්පත් (Natural Resources, Energy & Water)
 */
internal object GeographyLiveExamResourcesBank {
  private fun q(t: String, s: String, c: String, d1: String, d2: String, d3: String, e: String) =
    QSpec(t, s, c, listOf(d1, d2, d3), e)

  fun naturalResourcesQuestions(): List<QSpec> {
    val t = "ස්වාභාවික සම්පත්, බලශක්ති හා ජල සම්පත්"
    return listOf(
      q(t, "ස්වාභාවික සම්පත් වර්ගීකරණයේදී 'පුනර්ජනනීය සම්පත්' (Renewable Resources) සහ 'පුනර්ජනනීය නොවන සම්පත්' (Non-Renewable Resources) අතර ප්‍රධාන වෙනස කුමක්ද?",
        "පුනර්ජනනීය සම්පත් මිනිස් කාල පරාසයක් තුළ ස්වාභාවිකව නැවත පිරෙන අතර පුනර්ජනනීය නොවන සම්පත් සෑදීමට වසර මිලියන ගණනක් ගත වන බැවින් භාවිතයත් සමඟ ක්ෂය වේ", "පුනර්ජනනීය සම්පත් පොළොව යට පමණක් පවතී", "ගල් අඟුරු පුනර්ජනනීය සම්පතකි", "සූර්ය ශක්තිය ක්ෂය වේ",
        "සූර්ය රශ්මිය, සුළං, ජලය හා වනාන්තර පුනර්ජනනීය වන අතර ඛනිජ තෙල්, ගල් අඟුරු හා ඛනිජ වර්ග ක්ෂය වන සම්පත් වේ."),
      q(t, "පොසිල ඉන්ධන (Fossil Fuels) ලෙස හඳුන්වනු ලබන ප්‍රධාන බලශක්ති ප්‍රභව තුන මොනවාද?",
        "ගල් අඟුරු, බොරතෙල් (ඛනිජ තෙල්) සහ ස්වාභාවික වායු", "සූර්ය, සුළං සහ උදම් ශක්තිය", "භූ තාපජ, ජල විදුලි සහ දැව", "යුරේනියම්, රන් සහ මිනිරන්",
        "වසර මිලියන ගණනකට පෙර වැළලුණු ශාක හා සාගර ජීවීන්ගේ අවශේෂ ඉහළ පීඩනය හා තාපය යටතේ පොසිල ඉන්ධන බවට පත් විය."),
      q(t, "ගල් අඟුරු වර්ග අතර ඉහළම කාබන් ප්‍රතිශතයක් (~90%–95%) සහ වැඩිම තාප ශක්තියක් ලබා දෙන, අඩුම දුමාරයක් සහිත උසස්ම ගල් අඟුරු වර්ගය කුමක්ද?",
        "ඇන්ත්‍රසයිට් (Anthracite)", "පීට් (Peat)", "ලිග්නයිට් (Lignite)", "බිටුමිනස් (Bituminous)",
        "ශාක අවශේෂ පීට් → ලිග්නයිට් → බිටුමිනස් → ඇන්ත්‍රසයිට් ලෙස ක්‍රමයෙන් තද ගල් අඟුරු බවට පරිණාමය වේ."),
      q(t, "ලොව බොරතෙල් සංචිත අතින් ප්‍රමුඛතම කලාපය වන මැදපෙරදිග පර්සියානු ගල්ෆ් කලාපයේ ප්‍රධාන තෙල් නිෂ්පාදක රටවල් මොනවාද?",
        "සෞදි අරාබිය, ඉරානය, ඉරාකය, කුවේටය සහ එක්සත් අරාබි එමීර් රාජ්‍යය", "ජපානය සහ දකුණු කොරියාව", "ස්විට්සර්ලන්තය සහ ඔස්ට්‍රියාව", "ශ්‍රී ලංකාව සහ නේපාලය",
        "ලෝක තෙල් මිල හා නිෂ්පාදන සීමා සම්බන්ධීකරණය කිරීමට OPEC සංවිධානය ප්‍රධාන කාර්යභාරයක් ඉටු කරයි."),
      q(t, "'ස්වාභාවික වායු' (Natural Gas - ප්‍රධාන වශයෙන් මීතේන්) ගල් අඟුරු හා තෙල්වලට වඩා 'පිරිසිදු පොසිල ඉන්ධනයක්' ලෙස සැලකෙන්නේ ඇයි?",
        "එය දහනයේදී ගල් අඟුරුවලට වඩා ~50% ක් අඩුවෙන් කාබන් ඩයොක්සයිඩ් හා අවම සල්ෆර්/අළු ප්‍රමාණයක් පිට කරන බැවින්", "එය දහනයේදී ඔක්සිජන් පිට කරන නිසා", "එය පුනර්ජනනීය නිසා", "එය කාබන් රහිත නිසා",
        "කෙසේ වෙතත් එය තවමත් හරිතාගාර වායු පිට කරන ක්ෂය වන සම්පතකි."),
      q(t, "න්‍යෂ්ටික බලාගාරවල (Nuclear Power Plants) විදුලිය නිපදවීම සඳහා බහුලවම භාවිත කරන විකිරණශීලී ඛනිජ ඉන්ධනය කුමක්ද?",
        "යුරේනියම් (Uranium-235)", "තඹ", "බොක්සයිට්", "හුණුගල්",
        "න්‍යෂ්ටික විඛණ්ඩනය (Fission) මගින් අතිවිශාල තාපයක් නිපදවෙන අතර හරිතාගාර වායු පිට නොවුවද විකිරණශීලී අපද්‍රව්‍ය හා අනතුරු අවදානම් (චර්නොබිල්, ෆුකුෂිමා) පවතී."),
      q(t, "'ජල විදුලි බලය' (Hydroelectric Power - HEP) නිපදවීම සඳහා වඩාත්ම සුදුසු භෞතික භූගෝලීය පිහිටීම කුමක්ද?",
        "වසර පුරා අධික වර්ෂාපතනයක්, තද බෑවුම් හා පටු ගැඹුරු නිම්න (වේල්ලක් බැඳීමට සුදුසු ශක්තිමත් පාෂාණ පදනම) සහිත කඳුකර ගංගා", "පැතලි කාන්තාර", "වැලි වෙරළ", "සෘතුමය වියළි ඇළවල්",
        "නෝර්වේ, කැනඩාව, බ්‍රසීලය, චීනය (ත්‍රී ගෝර්ජස්) හා ශ්‍රී ලංකාවේ මධ්‍යම කඳුකරය ජල විදුලියට ප්‍රසිද්ධය."),
      q(t, "සූර්ය බලශක්තිය (Solar Energy) ප්‍රධාන ආකාර දෙකකින් ප්‍රයෝජනයට ගැනේ; ඒවා මොනවාද?",
        "සූර්ය පැනල (Photovoltaic Cells) මගින් සෘජුව විදුලිය නිපදවීම සහ සූර්ය තාප (Solar Thermal) පද්ධති මගින් ජලය රත් කිරීම/වාෂ්ප ටර්බයින කරකැවීම", "හඳ එළියෙන් විදුලිය ගැනීම", "වැසි ජලයෙන් තාපය ගැනීම", "සුළඟින් ආලෝකය සෑදීම",
        "නිවර්තන හා උප-නිවර්තන කාන්තාර කලාප මෙන්ම ශ්‍රී ලංකාවේ වියළි කලාපයද සූර්ය බල උද්‍යාන (උදා: සියඹලාණ්ඩුව/හම්බන්තොට) සඳහා ඉතා සුදුසුය."),
      q(t, "සුළං බලශක්ති (Wind Energy) ටර්බයින ගොඩබිමට වඩා මුහුදේ (Offshore Wind Farms) ඉදි කිරීමේදී ලැබෙන ප්‍රධාන වාසිය කුමක්ද?",
        "සාගර මතුපිට බාධක නොමැති නිසා සුළඟ වඩාත් වේගවත් හා ස්ථාවර වීමත් ගොඩබිම් ඉඩම් හිඟය හා ශබ්ද බාධා මගහැරීමත්", "මුහුදේ සුළඟ නොමැති වීම", "මාළුන්ට විදුලිය දීම", "ටර්බයින මල නොබැඳීම",
        "උතුරු මුහුදේ (ඩෙන්මාර්කය, එක්සත් රාජධානිය, ජර්මනිය) විශාල Offshore සුළං බලාගාර පිහිටුවා ඇත."),
      q(t, "'භූ තාපජ බලශක්තිය' (Geothermal Energy) ඉතා සාර්ථකව විදුලිය හා උණුසුම සඳහා යොදා ගන්නා රටවල් (අයිස්ලන්තය, නවසීලන්තය, පිලිපීනය, කෙන්යාව) කුමන භූ විද්‍යාත්මක කලාපවල පිහිටා තිබේද?",
        "භූ තැටි සීමාවන්හි හා සක්‍රීය ගිනිකඳු කලාපවල (පොළොව මතුපිටට ආසන්නව උණුසුම් මැග්මා හා පාෂාණ පවතින පෙදෙස්)", "ස්ථාවර පුරාණ පළිහ මැද", "කොරල් දූපත්වල පමණි", "සහරා කාන්තාරය මැද",
        "අයිස්ලන්තයේ නිවාස උණුසුම් කිරීමෙන් 90% කට වඩා සිදුවන්නේ භූ තාපජ ශක්තියෙනි."),
      q(t, "'උදම් ශක්තිය' (Tidal Energy) සූර්ය හා සුළං ශක්තියට වඩා විශේෂ වාසියක් ලබා දෙන්නේ කුමන හේතුව නිසාද?",
        "චන්ද්‍රයාගේ හා සූර්යයාගේ ගුරුත්වාකර්ෂණය මත වඩදිය-බාදිය ඉතා නිවැරදිව හා පුරෝකථනය කළ හැකි රටාවකට සිදුවීම", "රාත්‍රියේ වැඩ නොකිරීම", "සෑම කන්දකම පැවතීම", "මිරිදිය ගංගාවල පමණක් පැවතීම",
        "වඩදිය-බාදිය උස පරතරය අධික පටු මෝයවල් (උදා: ප්‍රංශයේ ලා රාන්ස්) මේ සඳහා යොදා ගැනේ."),
      q(t, "'ජෛව ස්කන්ධ බලශක්තිය' (Biomass Energy) යනු කුමක්ද?",
        "දර, කෘෂිකාර්මික අපද්‍රව්‍ය (පිදුරු, දහයියා, උක් රොඩු), සත්ත්ව ගොම (ජීව වායු) හා ජෛව ඉන්ධන වැනි කාබනික ද්‍රව්‍යවලින් ලබාගන්නා බලශක්තියයි", "යුරේනියම් විඛණ්ඩනයයි", "භූ තාපයයි", "සුළං ටර්බයිනයයි",
        "ග්‍රාමීය ප්‍රදේශවල ජීව වායු ඒකක මගින් මීතේන් වායුව ඉවුම්-පිහුම් සඳහාත් ඉතිරි මඩ කාබනික පොහොර ලෙසත් භාවිත කෙරේ."),
      q(t, "ලෝකයේ සමස්ත ජලයෙන් 97.5% ක් සාගර හා ලවණ ජලය වන විට, ඉතිරි 2.5% ක් වන මිරිදිය ජලයෙන් වැඩිම කොටසක් (~68.7%) රැඳී ඇත්තේ කොතැනද?",
        "ඇන්ටාක්ටිකාව, ග්‍රීන්ලන්තය හා උස් කඳු මුදුන්වල අයිස් තට්ටු සහ ග්ලැසියර ලෙස", "ගංගා සහ ඇළ දොළවල", "වායුගෝලයේ වලාකුළුවල", "වැව්වල",
        "මිනිසුන්ට පහසුවෙන් ලබාගත හැකි මතුපිට මිරිදිය (ගංගා, විල්) මුළු පෘථිවි ජලයෙන් 1% කටත් වඩා අඩුය."),
      q(t, "'භූගත ජලධරය' (Aquifer) යනු ජල සම්පත් භූගෝල විද්‍යාවේ කුමන භූ විද්‍යාත්මක සැකැස්මක්ද?",
        "ජලය රඳවා ගැනීමට හා ගලා යාමට ඉඩ සලසන සවිවර හා පාරගම්‍ය පාෂාණ හෝ වැලි/බොරළු ස්තරයක්", "අපාරගම්‍ය ග්‍රැනයිට් ගල් කුට්ටියක්", "මතුපිට ඇළ මාර්ගයක්", "කොරල්පරයක්",
        "නළ ළිං මගින් අධික ලෙස භූගත ජලය පොම්ප කිරීමෙන් ජල මට්ටම පහත වැටීම (Water Table Depletion) හා වෙරළබඩ ලවණ ජලය ඇතුළු වීම (Saltwater Intrusion) සිදුවේ."),
      q(t, "'ආටීසියානු ද්‍රෝණිය' (Artesian Basin) කාන්තාර හා අර්ධ ශුෂ්ක පෙදෙස්වල (උදා: ඔස්ට්‍රේලියාවේ මහා ආටීසියානු ද්‍රෝණිය) ජල සැපයුමට වැදගත් වන්නේ ඇයි?",
        "අපාරගම්‍ය පාෂාණ ස්තර දෙකක් අතර පීඩනය යටතේ සිර වී ඇති භූගත ජලය, ළිඳක් හෑරූ විට පොම්ප කිරීමකින් තොරවම ස්වාභාවික පීඩනයෙන් ඉහළට මතුවන බැවින්", "එහි ජලය තෙල් වැනි නිසා", "සෑම දිනකම වැසි වසින නිසා", "හිම දියවන නිසා",
        "කඳුකර ප්‍රදේශයකින් උරාගන්නා වැසි ජලය භූගතව කිලෝමීටර් සිය ගණනක් ඈත තැනිතලාව දක්වා ගමන් කරයි."),
      q(t, "ගෝලීය වශයෙන් පිරිසිදු මිරිදිය ජලයෙන් වැඩිම ප්‍රතිශතයක් (~70% ක් පමණ) පරිභෝජනය කරනු ලබන ආර්ථික අංශය කුමක්ද?",
        "කෘෂිකර්මාන්තය (වාරිමාර්ග හා පශු සම්පත්)", "ගෘහස්ථ පානය හා සේදීම (~10%)", "කර්මාන්ත අංශය (~20%)", "පිහිනුම් තටාක",
        "එබැවින් බිංදු ජල සම්පාදනය (Drip Irrigation) වැනි කාර්යක්ෂම වාරි ක්‍රම ජල සංරක්ෂණයේදී අතිශයින් වැදගත් වේ."),
      q(t, "'භෞතික ජල හිඟය' (Physical Water Scarcity) සහ 'ආර්ථික ජල හිඟය' (Economic Water Scarcity) අතර වෙනස කුමක්ද?",
        "භෞතික ජල හිඟය යනු කලාපයේ ස්වාභාවික ජල සැපයුම ඉල්ලුමට වඩා අඩු වීම වන අතර ආර්ථික ජල හිඟය යනු ජලය පැවතුණද එය පිරිපහදු කර බෙදා හැරීමට මුදල් හා යටිතල පහසුකම් නොමැති වීමයි", "දෙකම කාන්තාරවල පමණි", "ආර්ථික හිඟයේදී වැසි නොවසී", "වෙනසක් නැත",
        "මැදපෙරදිග රටවල් භෞතික ජල හිඟයෙන්ද, මධ්‍යම අප්‍රිකාවේ සමහර රටවල් ආර්ථික ජල හිඟයෙන්ද පීඩා විඳී."),
      q(t, "'මුහුදු ජලය ලවණහරණය කිරීම' (Desalination) බහුලව භාවිත කරන නමුත් එහි ඇති ප්‍රධාන පාරිසරික හා ආර්ථික අවාසිය කුමක්ද?",
        "ඉතා අධික විදුලි/තාප බලශක්තියක් වැය වීමත්, ඉවතලන අධි-සාන්ද්‍රිත ලුණු ද්‍රාවණය (Brine) සාගර පරිසර පද්ධතිවලට හානි කිරීමත්", "ජලය පානයට නුසුදුසු වීම", "ලුණු නොමැති වීම", "වැසි වැඩිවීම",
        "සෞදි අරාබිය, ඊශ්‍රායලය හා එක්සත් අරාබි එමීර් රාජ්‍යය සිය පානීය ජල අවශ්‍යතාවයෙන් විශාල කොටසක් ප්‍රතිලෝම ආස්‍රැතිය (Reverse Osmosis) මගින් සපුරා ගනී."),
      q(t, "යකඩ හා වානේ නිෂ්පාදනයේ මූලික ලෝහමය ඛනිජය වන 'යපස්' (Iron Ore) ලෝකයේ ප්‍රධාන වශයෙන් කැණීම් කරනු ලබන රටවල් මොනවාද?",
        "ඔස්ට්‍රේලියාව (පිල්බරා), බ්‍රසීලය (කරජාස්), චීනය සහ ඉන්දියාව", "ශ්‍රී ලංකාව සහ මාලදිවයින", "නෝර්වේ සහ අයිස්ලන්තය", "සිංගප්පූරුව සහ හොංකොං",
        "හෙමටයිට් (Hematite) හා මැග්නටයිට් (Magnetite) ඉහළ යකඩ ප්‍රතිශතයක් අඩංගු ප්‍රධාන යපස් වර්ග වේ."),
      q(t, "ඇලුමිනියම් ලෝහය නිස්සාරණය කිරීම සඳහා අත්‍යවශ්‍ය ප්‍රධාන අමුද්‍රව්‍ය ලෝපස කුමක්ද?",
        "බොක්සයිට් (Bauxite)", "කැසිටරයිට් (ටින්)", "ගැලීනා (ඊයම්)", "කෝල්ටන්",
        "නිවර්තන කාලගුණික ජීර්ණයෙන් සෑදෙන බොක්සයිට් ප්‍රධාන වශයෙන් ඔස්ට්‍රේලියාව, ගිනියාව, චීනය හා බ්‍රසීලයෙන් නිපදවේ."),
      q(t, "විදුලි කම්බි, ඉලෙක්ට්‍රොනික පරිපථ සහ විදුලි වාහන නිෂ්පාදනයේදී ඉහළ විද්‍යුත් සන්නායකතාවය නිසා අත්‍යවශ්‍ය ඛනිජ ලෝහය කුමක්ද?",
        "තඹ (Copper - චිලී සහ පේරු ප්‍රමුඛ නිෂ්පාදකයෝ වෙති)", "මයිකා", "ජිප්සම්", "හුණුගල්",
        "ඇන්ඩීස් කඳුකරයේ චිලී රාජ්‍යය ලොව විශාලතම තඹ නිෂ්පාදකයා වේ."),
      q(t, "වර්තමාන ස්මාර්ට්ෆෝන්, ලැප්ටොප් සහ විදුලි වාහන බැටරි (EV Batteries) නිපදවීමේදී තීරණාත්මක ඛනිජ (Critical Minerals) ලෙස සැලකෙන්නේ මොනවාද?",
        "ලිතියම් (Lithium), කොබෝල්ට් (Cobalt), නිකල් (Nickel) සහ දුර්ලභ පස් මූලද්‍රව්‍ය (Rare Earth Elements)", "වැලි සහ මැටි", "හුණුගල් සහ ග්‍රැනයිට්", "සල්ෆර් සහ ජිප්සම්",
        "දකුණු ඇමරිකාවේ 'ලිතියම් ත්‍රිකෝණය' (චිලී, බොලිවියාව, ආර්ජන්ටිනාව) සහ කොංගෝවේ කොබෝල්ට් නිධි ගෝලීය හරිත බලශක්ති සංක්‍රාන්තියට තීරණාත්මකය."),
      q(t, "'විවෘත පතල් කැණීම' (Open-pit / Surface Mining) භූගත පතල් කැණීමට වඩා ආර්ථික වශයෙන් ලාභදායී වුවද ඉන් සිදුවන ප්‍රධාන පාරිසරික හානිය කුමක්ද?",
        "විශාල භූමි ප්‍රදේශයක වනාන්තර හා මතුපිට පස ඉවත් වීම, ගැඹුරු ආවාට සෑදීම, දූවිලි හා අම්ල පතල් ජල වහනය (Acid Mine Drainage)", "මුහුදු රළ වැඩිවීම", "හිම කඳු ඇතිවීම", "පොළොව යට තාපය අඩුවීම",
        "පතල් කැණීම අවසන් වූ පසු එම භූමිය ප්‍රතිසංස්කරණය කර (Mine Reclamation) නැවත වනාන්තර හෝ ජලාශ බවට පත් කළ යුතුය."),
      q(t, "ශ්‍රී ලංකාවේ වයඹදිග පුත්තලමේ 'අරුවක්කාලු' හා උතුරේ 'කන්කසන්තුරේ' ප්‍රදේශවල කැණීම් කරනු ලබන සිමෙන්ති නිෂ්පාදනයට අවශ්‍ය ප්‍රධාන ඛනිජය කුමක්ද?",
        "මයෝසීන හුණුගල් (Miocene Limestone)", "මිනිරන්", "මැණික්", "යපස්",
        "ශ්‍රී ලංකාවේ උතුරු හා වයඹ තීරයේ ව්‍යාප්තව ඇති පාෂාණගත මයෝසීන හුණුගල් සිමෙන්ති හා ඉදිකිරීම් කර්මාන්තයට ඉතා වැදගත් වේ."),
      q(t, "ශ්‍රී ලංකාවේ 'එප්පාවල' (අනුරාධපුර දිස්ත්‍රික්කය) ප්‍රදේශයේ පිහිටි ප්‍රධාන ඛනිජ නිධිය කුමක්ද?",
        "රොක් පොස්පේට් (Apatite / Rock Phosphate) නිධිය", "රන් නිධිය", "ගල් අඟුරු නිධිය", "තඹ නිධිය",
        "පොහොර නිෂ්පාදනයේදී පොස්පරස් ප්‍රභවයක් ලෙස එප්පාවල ඇපටයිට් නිධිය භාවිත කෙරේ."),
      q(t, "ශ්‍රී ලංකාවේ ඊසානදිග වෙරළේ 'පුල්මුඩේ' (ත්‍රිකුණාමලයට උතුරින්) ප්‍රදේශයේ බහුලව හමුවන ලෝක ප්‍රසිද්ධ කළු වැලි ඛනිජ සම්පත මොනවාද?",
        "ඉල්මනයිට්, රූටයිල් සහ සර්කෝන් (Ilmenite, Rutile, Zircon - බර ඛනිජ වැලි)", "ඩොලමයිට් හා හුණුගල්", "මිනිරන් හා මයිකා", "සෙල්ලම් මැටි",
        "ටයිටේනියම් වර්ණක, අභ්‍යවකාශ උපාංග හා පිඟන් කර්මාන්ත සඳහා ඉල්මනයිට් හා රූටයිල් අපනයනය කෙරේ."),
      q(t, "'වනාන්තර සම්පත' (Forest Resources) 'පෘථිවියේ පෙනහළු' ලෙස හඳුන්වනු ලබන්නේ කුමන පාරිසරික සේවාව නිසාද?",
        "ප්‍රභාසංශ්ලේෂණය මගින් වායුගෝලීය කාබන් ඩයොක්සයිඩ් (CO2) අවශෝෂණය කර කාබන් ගබඩා කිරීමත්, ඔක්සිජන් මුදා හැරීමත්", "ජලය ලවණ කිරීම නිසා", "ගිනිකඳු නිවීම නිසා", "පාෂාණ කැඩීම නිසා",
        "මීට අමතරව වනාන්තර පාංශු ඛාදනය වළක්වා, ගංගා ජල පෝෂක රැක දී ජෛව විවිධත්වයට වාසභූමි සපයයි."),
      q(t, "'සමාජ වන වගාව' (Social Forestry / Community Forestry) සංකල්පයේ ප්‍රධාන අරමුණ කුමක්ද?",
        "දැව, දර, පලතුරු හා පාරිසරික ආරක්ෂාව සඳහා ප්‍රාදේශීය ග්‍රාමීය ජනතාවගේ සහභාගීත්වයෙන් හිස් ඉඩම්, මාර්ග දෙපස හා ගෙවතුවල ගස් වැවීම", "වනාන්තර සම්පූර්ණයෙන් කපා විකිණීම", "ජනතාව වනාන්තරවලින් පලවා හැරීම", "කොන්ක්‍රීට් බැමි බැඳීම",
        "ග්‍රාමීය ජනතාවට ආදායමක් හා දර ලැබෙන විට ස්වාභාවික වනාන්තර විනාශ වීම අඩු වේ."),
      q(t, "'මුහුදු සම්පත්' අතර රටක වෙරළේ සිට නාවික සැතපුම් 200 ක් දක්වා විහිදෙන 'අනන්‍ය ආර්ථික කලාපය' (Exclusive Economic Zone - EEZ) තුළ රටට හිමි අයිතිය කුමක්ද?",
        "එම සාගර ජලයේ හා මුහුදු පතුලේ ඇති මත්ස්‍ය සම්පත්, ඛනිජ තෙල්, වායු හා ඛනිජ ගවේෂණය, සංරක්ෂණය හා ප්‍රයෝජනයට ගැනීමේ සුවිශේෂී අයිතිය", "අනෙක් රටවල නැව් ගමන් සම්පූර්ණයෙන් තහනම් කිරීම", "සාගරය ගොඩකර ගොඩනැගිලි තැනීම", "සාගර ජලය බීමට විකිණීම",
        "UNCLOS ගිවිසුම යටතේ ශ්‍රී ලංකාවට සිය ගොඩබිම් ප්‍රමාණය මෙන් ~8 ගුණයකට ආසන්න විශාල EEZ සාගර කලාපයක් හිමිය."),
      q(t, "ධීවර කර්මාන්තයේදී 'පෙලැජික් මත්ස්‍යයන්' (Pelagic Fish) සහ 'ඩෙමර්සල් මත්ස්‍යයන්' (Demersal Fish) වෙන්කර හඳුනාගන්නේ කෙසේද?",
        "පෙලැජික් මසුන් (කෙළවල්ලා, බලයා, හුරුල්ලා) සාගරයේ මතුපිට/ඉහළ ජල ස්තරවල ජීවත් වන අතර ඩෙමර්සල් මසුන් (පරා, තෝරා, කලවා/මුහුදු පතුලේ මසුන්) පතුල ආසන්නයේ ජීවත් වේ", "පෙලැජික් මසුන් මිරිදිය මසුන්ය", "ඩෙමර්සල් මසුන් පියාඹයි", "කිසිදු වෙනසක් නැත",
        "වැඩි වශයෙන් ශීත හා උණුසුම් සාගර දියවැල් හමුවන මහාද්වීපික තටාක (උදා: නිව්ෆවුන්ඩ්ලන්ඩ් ග්‍රෑන්ඩ් බෑන්ක්ස්, ජපානය අවට) ලොව ප්‍රධාන ධීවර කලාප වේ."),
      q(t, "'ජලජීවී වගාව' (Aquaculture / Fish Farming) වර්තමාන ලෝක ආහාර සුරක්ෂිතතාවයේදී වැදගත් වන්නේ ඇයි?",
        "ස්වාභාවික සාගරවල අධික මසුන් ඇල්ලීම (Overfishing) නිසා මත්ස්‍ය සංචිත ක්ෂය වීම අඩු කර පාලිත තත්ත්ව යටතේ මසුන්, ඉස්සන් හා බෙල්ලන් නිපදවීමට", "සාගර මසුන් සියල්ල විනාශ කිරීමට", "මිරිදිය විල් හිස් කිරීමට", "ධීවරයන් ඉවත් කිරීමට",
        "කෙසේ වෙතත් වෙරළබඩ කඩොලාන කපා අවිධිමත්ව ඉස්සන් කොටු ඉදිකිරීම පාරිසරික හානි ඇති කරයි."),
      q(t, "'පස' (Soil) අගනා නමුත් පහසුවෙන් ක්ෂය වන සම්පතක් ලෙස සලකන්නේ ඇයි?",
        "සාරවත් මතුපිට පස් අඟලක් ස්වාභාවිකව සෑදීමට වසර සිය ගණනක් ගත වුවද වැරදි වගා ක්‍රම හා වන විනාශයෙන් එය කන්න කිහිපයකින් සෝදා යා හැකි බැවින්", "පස කිසිදා නොසේදෙන බැවින්", "පස ලෝහයකින් සෑදී ඇති බැවින්", "පස කෘත්‍රිමව කර්මාන්තශාලාවල හදන බැවින්",
        "සමෝච්ච වගාව (Contour Ploughing), ගල් වැටි (Terracing), බහු වගාව සහ වසුන් යෙදීම (Mulching) ප්‍රධාන පාංශු සංරක්ෂණ ක්‍රම වේ."),
      q(t, "'මුදුන් කඳු වැටිවල වගා කරන විට හෙල්මළු ක්‍රමය (Terracing) භාවිත කිරීම' සම්පත් සංරක්ෂණයට උපකාරී වන්නේ කෙසේද?",
        "දළ බෑවුම කුඩා පැතලි පඩි බවට පත් කර වැසි ජලය ගලා යාමේ වේගය අඩු කර පාංශු ඛාදනය වැළැක්වීම හා ජලය පසට උරා ගැනීම වැඩි කිරීම", "පස ඉක්මනින් සෝදා හැරීම", "නායයෑම් වැඩි කිරීම", "ජලය නාස්ති කිරීම",
        "පිලිපීනයේ ඉෆුගාඕ, චීනයේ යුනාන් හා ශ්‍රී ලංකාවේ කඳුකර හෙල්මළු වී කුඹුරු මීට සාර්ථක උදාහරණ වේ."),
      q(t, "'චක්‍රීය ආර්ථිකය' (Circular Economy) සම්ප්‍රදායික 'රේඛීය ආර්ථිකයට' (Take-Make-Waste) වඩා තිරසාර වන්නේ ඇයි?",
        "සම්පත් එක් වරක් භාවිත කර ඉවත දැමීම වෙනුවට අලුත්වැඩියා කිරීම (Repair), නැවත භාවිතය (Reuse) සහ ප්‍රතිචක්‍රීකරණය (Recycle) මගින් ද්‍රව්‍ය දිගටම චක්‍රය තුළ තබා ගැනීම", "වැඩිපුර කසළ නිපදවීම නිසා", "ඛනිජ වේගයෙන් කැණීම නිසා", "සියලු භාණ්ඩ පුළුස්සා දැමීම නිසා",
        "මෙමගින් අමුද්‍රව්‍ය නිස්සාරණය හා පාරිසරික අපද්‍රව්‍ය බැහැර කිරීම අවම කෙරේ."),
      q(t, "'ස්වාභාවික ජල චක්‍රයේ' (Hydrological Cycle) සිදුවන ප්‍රධාන ක්‍රියාවලි හතර කවරේද?",
        "වාෂ්පීභවනය හා උත්ස්වේදනය, ඝනීභවනය, වර්ෂාපතනය සහ මතුපිට/භූගත ගලා යාම", "ඛාදනය, නැමීම, විභේදනය සහ පිපිරීම", "කැණීම, පිරිපහදුව, විකිණීම සහ බැහැර කිරීම", "හිරු නැගීම සහ බැසීම",
        "මිරිදිය සම්පත අඛණ්ඩව පවතින්නේ සූර්ය ශක්තියෙන් හා ගුරුත්වයෙන් ක්‍රියාත්මක වන මෙම ජල චක්‍රය නිසාය."),
      q(t, "'වැසි ජල රැස් කිරීම' (Rainwater Harvesting) නාගරික හා වියළි කලාපීය නිවාසවල ප්‍රවර්ධනය කරන්නේ ඇයි?",
        "වහලයට වැටෙන පිරිසිදු වැසි ජලය ටැංකිවල ගබඩා කර වියළි කාලයේදී භාවිතයට ගැනීමෙන් නළ ජල ඉල්ලුම හා නාගරික ගංවතුර පීඩනය අඩු කිරීමට", "වැසි වැළැක්වීමට", "වහල කැඩීමට", "ලුණු නිපදවීමට",
        "ශ්‍රී ලංකාවේ නව ගොඩනැගිලි රෙගුලාසි යටතේ වැසි ජල රැස් කිරීමේ පද්ධති දිරිමත් කෙරේ."),
      q(t, "බලශක්ති ක්ෂේත්‍රයේ 'ස්මාර්ට් ජාලය' (Smart Grid) යන්නෙන් අදහස් කරන්නේ කුමක්ද?",
        "නිවාසවල වහල මත සූර්ය පැනල, බැටරි ගබඩා හා බලාගාර අතර ද්වි-මාර්ග ඩිජිටල් සන්නිවේදනයෙන් විදුලි සැපයුම හා ඉල්ලුම ක්ෂණිකව සමතුලිත කරන ජාලය", "විදුලි රැහැන් ඉවත් කිරීම", "ගල් අඟුරු පමණක් භාවිතය", "රාත්‍රියේ විදුලිය කපා හැරීම",
        "පුනර්ජනනීය බලශක්ති උච්චාවචනයන් කළමනාකරණය කිරීමට Smart Grid හා මහා පරිමාණ බැටරි ගබඩා අත්‍යවශ්‍ය වේ."),
      q(t, "'හරිත හයිඩ්‍රජන්' (Green Hydrogen) අනාගත බලශක්ති ප්‍රභවයක් ලෙස වැදගත් වන්නේ ඇයි?",
        "සූර්ය හෝ සුළං විදුලිය යොදා ජලය විද්‍යුත් විච්ඡේදනය කිරීමෙන් (Electrolysis) නිපදවන හයිඩ්‍රජන් දහනයේදී කාබන් රහිතව ජල වාෂ්ප පමණක් පිටවන බැවින්", "එය ගල් අඟුරුවලින් හදන නිසා", "එය දහනයෙන් CO2 පිටවන නිසා", "එය භූගත පතල්වලින් ගන්නා නිසා",
        "වානේ කර්මාන්තය, නැව් හා ගුවන් යානා ප්‍රවාහනය කාබන්හරණය කිරීමට හරිත හයිඩ්‍රජන් ඉතා ප්‍රයෝජනවත් වේ."),
      q(t, "ශ්‍රී ලංකාවේ විදුලිබල උත්පාදනයේ 'තෙත් කාලයේ හා වියළි කාලයේ' පවතින ප්‍රධාන අභියෝගය කුමක්ද?",
        "වැසි කාලයේදී ජලාශ පිරී ලාභදායී ජල විදුලිය වැඩි වශයෙන් ලැබුණද, නියං සමයේදී ආනයනික ඩීසල්, දැවිතෙල් හා ගල් අඟුරු මත දැඩි ලෙස යැපීමට සිදුවීම", "වැසි කාලයේ විදුලිය නිපදවීමට නොහැකි වීම", "ශ්‍රී ලංකාවේ හිරු එළිය නොමැති වීම", "ගල් අඟුරු රට තුළම තිබීම",
        "මන්නාරමේ සුළං බලාගාර ('තම්බපවනි') හා වහල මත සූර්ය පැනල මගින් මෙම ආනයනික පොසිල ඉන්ධන යැපීම අඩු කිරීමට පියවර ගෙන ඇත."),
      q(t, "ශ්‍රී ලංකාවේ 'මන්නාරම දූපත' හා 'හම්බන්තොට' ප්‍රදේශ විශේෂයෙන් ප්‍රචලිත වී ඇත්තේ කුමන පුනර්ජනනීය බලශක්ති ප්‍රභවය සඳහාද?",
        "සුළං බලශක්තිය හා සූර්ය බලශක්තිය", "භූ තාපජ බලශක්තිය", "න්‍යෂ්ටික බලශක්තිය", "ග්ලැසියර ජල විදුලිය",
        "මෝසම් දෙකෙන්ම ලැබෙන ශක්තිමත් වෙරළබඩ සුළං ධාරා මන්නාරම සුළං විදුලි බලාගාරයට ඉතා සුදුසුය."),
      q(t, "'ජල පෝෂක ප්‍රදේශයක්' (Water Catchment / Watershed) ආරක්ෂා කිරීම යනු කුමක්ද?",
        "ගංගාවකට හෝ ජලාශයකට වැසි ජලය එකතු වන ඉහළ කඳුකර වනාන්තර හා තෙත් බිම් හෙළි නොකර, රසායනික ද්‍රව්‍යවලින් දූෂණය නොවී රැක ගැනීම", "ගංගා මෝය වැලිවලින් වැසීම", "වනාන්තර කපා ගොඩනැගිලි තැනීම", "කඳු මුදුන් පුපුරුවා හැරීම",
        "ශ්‍රී ලංකාවේ හෝර්ටන් තැන්න, පීක් වයිල්ඩර්නස් (ශ්‍රී පාද අඩවිය) සහ නකල්ස් ප්‍රධාන ගංගා රැසක තීරණාත්මක ජල පෝෂක වේ."),
      q(t, "'තෙත් බිම්' (Wetlands - කඩොලාන, වගුරු, කලපු) වටිනා ස්වාභාවික සම්පතක් වන්නේ ඇයි?",
        "ගංවතුර ජලය ස්පොන්ජියක් මෙන් අවශෝෂණය කිරීම, ජලයේ අපද්‍රව්‍ය ස්වාභාවිකව පෙරීම, කාබන් ගබඩා කිරීම සහ මත්ස්‍ය හා පක්ෂි අභිජනන බිම් සැපයීම", "ඒවා මදුරුවන් පමණක් බෝ කරන නිසා", "ඒවා ගොඩකර කඩ සෑදීමට පමණක් සුදුසු නිසා", "කාබන් විමෝචනය වැඩි කරන නිසා",
        "රැම්සාර් සම්මුතිය (Ramsar Convention) ලොව වැදගත් තෙත් බිම් ආරක්ෂා කිරීම සඳහා ක්‍රියාත්මක වන අතර කොළඹ (තලංගම/දියසරු), බූන්දල හා මාදු ගඟ ශ්‍රී ලංකාවේ ප්‍රධාන තෙත් බිම් වේ."),
      q(t, "'බලශක්ති සංරක්ෂණය' (Energy Conservation) සහ 'බලශක්ති කාර්යක්ෂමතාව' (Energy Efficiency) අතර වෙනස කුමක්ද?",
        "බලශක්ති සංරක්ෂණය යනු පරිභෝජනය අඩු කිරීම (අනවශ්‍ය විදුලි බල්බ නිවා දැමීම) වන අතර කාර්යක්ෂමතාව යනු අඩු ශක්තියකින් එකම සේවාව ලබා ගැනීමයි (LED බල්බ භාවිතය)", "දෙකම එකම වේ", "කාර්යක්ෂමතාව යනු වැඩි විදුලියක් වැය කිරීමයි", "සංරක්ෂණය යනු ගල් අඟුරු දහනයයි",
        "දෙකම බලශක්ති පිරිවැය හා පාරිසරික දූෂණය අඩු කිරීමට සමානව වැදගත් වේ."),
      q(t, "'ජෛව විවිධත්ව උණුසුම් කලාපයක්' (Biodiversity Hotspot) ලෙස ශ්‍රී ලංකාව හා බටහිර ඝාට්ස් කලාපය නම් කර ඇත්තේ කුමන කරුණු මතද?",
        "ලෝකයේ වෙනත් කිසිදු තැනක නොමැති ආවේණික ශාක හා සත්ත්ව විශේෂ (Endemic Species) අතිවිශාල සංඛ්‍යාවක් සීමිත භූමියක පැවතීමත්, ඒවා දැඩි වාසභූමි අහිමි වීමේ තර්ජනයකට ලක්ව තිබීමත්", "උෂ්ණත්වය 60°C ඉක්මවන බැවින්", "ගිනිකඳු බහුල බැවින්", "කාන්තාර පවතින බැවින්",
        "සිංහරාජය, හෝර්ටන් තැන්න හා නකල්ස් ශ්‍රී ලංකාවේ මෙම අද්විතීය ජෛව සම්පත සුරකින මධ්‍යස්ථාන වේ."),
      q(t, "ලෝකයේ ප්‍රධාන තඹ, ටින්, රන් වැනි 'ලෝහමය ඛනිජ' බොහෝ විට හමුවන්නේ කුමන පාෂාණ කලාපවලද?",
        "පැරණි ප්‍රාග්-කේම්බ්‍රීය පළිහ (Precambrian Shields), නැමුණු කඳු වැටි සහ පැරණි ආග්නේය-විපරිත පාෂාණ කලාප", "අලුත් මුහුදු වැලි කඳු", "කොරල්පර පමණි", "අයිස් තට්ටු",
        "ඛනිජ තෙල්, ගල් අඟුරු හා ලුණු ප්‍රධාන වශයෙන් අවසාදිත පාෂාණ ද්‍රෝණිවල හමුවීම මීට වෙනස්ය."),
      q(t, "'ද්විතීයික බලශක්තියක්' (Secondary Energy Source) ලෙස විදුලි බලය හඳුන්වනු ලබන්නේ ඇයි?",
        "එය පොසිල ඉන්ධන, ජල ශක්තිය, සුළඟ හෝ සූර්ය ශක්තිය වැනි 'ප්‍රාථමික බලශක්ති ප්‍රභවයකින්' පරිවර්තනය කර නිපදවන බැවින්", "එය වැදගත් නොවන නිසා", "එය දෙවන වරට විකුණන නිසා", "එය පොළොව යටින් හාරා ගන්නා නිසා",
        "විදුලිය ප්‍රවාහනය හා භාවිතය ඉතා පිරිසිදු හා පහසු නමුත් එහි පාරිසරික බලපෑම රඳා පවතින්නේ එය නිපදවූ ප්‍රාථමික ප්‍රභවය මතය."),
      q(t, "'ජල පාද සටහන' (Water Footprint) යන්නෙන් මනිනු ලබන්නේ කුමක්ද?",
        "භාණ්ඩයක් හෝ සේවාවක් (උදා: කපු කමිසයක්, කෝපි කෝප්පයක්, මස් කිලෝග්‍රෑමයක්) නිපදවීමේ සම්පූර්ණ සැපයුම් දාමය තුළ වැය වන මුළු මිරිදිය ජල ප්‍රමාණය", "වැස්සේ වේගය", "පාවහන් ප්‍රමාණය", "ගංගාවේ ගැඹුර",
        "උදාහරණයක් ලෙස කපු ටී-ෂර්ට් එකක් නිපදවීමට කපු වගාවේ සිට රෙදි වර්ණ ගැන්වීම දක්වා ජලය ලීටර් ~2,500 කට වඩා වැය වේ."),
      q(t, "'අතථ්‍ය ජල වෙළඳාම' (Virtual Water Trade) මගින් ජල හිඟ රටවලට (උදා: ජෝර්දානය, ඊජිප්තුව, සෞදි අරාබිය) ලැබෙන වාසිය කුමක්ද?",
        "අධික ජලයක් වැය වන තිරිඟු හෝ සහල් වැනි භෝග තම රටේ වගා නොකර ජල සම්පත බහුල රටවලින් ආනයනය කිරීමෙන් සිය සීමිත දේශීය ජලය පානයට ඉතිරි කර ගැනීම", "පරිගණක තුළ ජලය පෙන්වීම", "වැසි වලාකුළු මිලදී ගැනීම", "මුහුදු ජලය අපනයනය",
        "එනම් ආනයනික ආහාර තුළ 'සැඟවුණු ජලය' රටට ආනයනය වීම සිදුවේ."),
      q(t, "'ඛනිජ සම්පත් ප්‍රතිචක්‍රීකරණය' (Metal Recycling - උදා: ඇලුමිනියම්, වානේ, තඹ) අලුතින් පතල් කැණීමට වඩා වාසිදායක වන්නේ ඇයි?",
        "ප්‍රතිචක්‍රීකරණයේදී 75%–95% දක්වා බලශක්තිය ඉතිරි වීම, ලෝපස් සංචිත රැක ගැනීම සහ පතල් අපද්‍රව්‍ය හා කාබන් විමෝචනය විශාල ලෙස අඩුවීම", "ලෝහ ගුණාත්මකභාවය නැති වීම", "වැඩිපුර ගල් අඟුරු වැය වීම", "කම්හල් වැසී යාම",
        "ඇලුමිනියම් හා වීදුරු ගුණාත්මකභාවය අඩු නොවී අනන්ත වාර ගණනක් ප්‍රතිචක්‍රීකරණය කළ හැකිය."),
      q(t, "'මහා පරිමාණ බහුකාර්ය ජලාශ ව්‍යාපෘති' (Multipurpose Dam Projects - උදා: ත්‍රී ගෝර්ජස්, හූවර්, අස්වාන්, වික්ටෝරියා) ඉදි කිරීමෙන් ලැබෙන ප්‍රධාන ප්‍රතිලාභ මොනවාද?",
        "වාරි ජල සැපයුම, ජල විදුලි උත්පාදනය, ගංවතුර පාලනය, පානීය ජල සැපයුම, මිරිදිය ධීවර කර්මාන්තය හා සංචාරක ආකර්ෂණය", "රටේ වර්ෂාපතනය නතර කිරීම", "කාන්තාර පුළුල් කිරීම", "මුහුදු මට්ටම ඉහළ දැමීම",
        "කෙසේ වෙතත් මෙම ව්‍යාපෘතිවලින් ඉඩම් යටවීම, ජනතාව අවතැන් වීම හා පහළ ඩෙල්ටාවට රොන්මඩ ගලා යාම අඩුවීම වැනි අභියෝගද ඇතිවේ."),
      q(t, "'කෘත්‍රිමව භූගත ජලය පෝෂණය කිරීම' (Artificial Groundwater Recharge) සිදු කරන්නේ කෙසේද?",
        "වැසි සමයේ අතිරික්ත ජලය කුඩා වැව්, ජල උරාගැනීමේ ළිං හෝ පොකුණු තුළ රඳවා පොළොව යට ජලධරවලට පෙරී යාමට සැලැස්වීමෙන්", "භූගත ජලය මුහුදට පොම්ප කිරීමෙන්", "පොළොව මතුපිට කොන්ක්‍රීට් ඇතිරීමෙන්", "ගස් කපා දැමීමෙන්",
        "ශ්‍රී ලංකාවේ පුරාණ ග්‍රාමීය වැව් පද්ධති අවට ගෙවතු හා ළිංවල ජල මට්ටම ඉහළ මට්ටමක තබා ගැනීමට මෙම කාර්යය ඉටු කරයි."),
      q(t, "'පොසිල ඉන්ධන මත යැපීම අවසන් කර පුනර්ජනනීය බලශක්තියට මාරු වීමේ' (Energy Transition) ප්‍රධාන අභියෝගයක් වන 'අතරමැදි ස්වභාවය' (Intermittency) යනු කුමක්ද?",
        "හිරු නොපායන රාත්‍රී හෝ වලාකුළු සහිත දිනවල සූර්ය බලයද, සුළඟ අඩු දිනවල සුළං බලයද අඩුවීම නිසා බැටරි ගබඩා හෝ ස්ථාවර උපස්ථ බලශක්තිය අවශ්‍ය වීම", "ටර්බයින ඉතා ලාභ වීම", "විදුලිය වැඩි වී නාස්ති වීම පමණි", "සූර්යයා කිසිදා නොබැසීම",
        "පොම්ප-ජල විදුලි (Pumped-Storage Hydro) සහ ලිතියම්-අයන් බැටරි පද්ධති මෙම ගැටලුව විසඳීමට යොදා ගනී."),
      q(t, "ජල සම්පත් කළමනාකරණයේ 'ඒකාබද්ධ ජල සම්පත් කළමනාකරණය' (IWRM - Integrated Water Resources Management) අවධාරණය කරන්නේ කුමක්ද?",
        "තනි ගංගා ද්‍රෝණියක් ඒකකයක් ලෙස සලකා කෘෂි, කාර්මික, ගෘහස්ථ හා පාරිසරික ජල අවශ්‍යතා සම්බන්ධීකරණයෙන් සාධාරණව කළමනාකරණය කිරීම", "එක් ගමක් පමණක් ජලය ගැනීම", "කර්මාන්තශාලාවලට අපද්‍රව්‍ය ගඟට දැමීමට ඉඩ දීම", "ජලය පෞද්ගලිකව සිර කර තැබීම",
        "පහළ ප්‍රදේශවල හා ඉහළ ජල පෝෂක ප්‍රදේශවල ප්‍රජාවන් අතර සහයෝගීතාව මෙහිදී අත්‍යවශ්‍ය වේ."),
      q(t, "'කඩොලාන පරිසර පද්ධති' (Mangroves) වෙරළබඩ සම්පතක් ලෙස ඉතා අගනා වන්නේ කුමන කරුණු නිසාද?",
        "සුනාමි හා කුණාටු රළවලින් වෙරළ ආරක්ෂා කිරීම, වෙරළ ඛාදනය වැළැක්වීම, කලපු මසුන් හා කකුළුවන් බෝවන තවානක් වීම සහ ඉහළ 'නිල් කාබන්' (Blue Carbon) ගබඩාවක් වීම", "වෙරළේ උෂ්ණත්වය වැඩි කිරීම", "මුහුදු ජලය විෂ කිරීම", "කොරල් විනාශ කිරීම",
        "ශ්‍රී ලංකාවේ පුත්තලම, කලමැටිය, මීගමුව හා මඩකලපුව කලපු ආශ්‍රිතව කඩොලාන සංරක්ෂණ ව්‍යාපෘති ක්‍රියාත්මක කෙරේ."),
      q(t, "පරිසරයට හා සම්පත්වලට සිදුවන හානිය අවම කරමින් මිනිස් අවශ්‍යතා සපුරන 'තිරසාර සම්පත් භාවිතය' (Sustainable Resource Use) නිර්වචනය කරන්නේ කෙසේද?",
        "අනාගත පරපුරේ අවශ්‍යතා සපුරා ගැනීමේ හැකියාවට හානි නොවන පරිදි වත්මන් පරපුරේ අවශ්‍යතා සපුරාලීම (Brundtland Report - 1987)", "අද සියලු සම්පත් අවසන් කිරීම", "කිසිදු සම්පතක් භාවිත නොකිරීම", "ගල් අඟුරු පමණක් භාවිතය",
        "තිරසාරභාවය පරිසරය, ආර්ථිකය හා සමාජය යන කුළුණු තුනෙහි සමතුලිතතාවය මත රඳා පවතී."),
      q(t, "ස්වාභාවික භූමි සම්පත් අතර 'පීට්' (Peat) සහ 'තෙත් බිම් පස්' කාබන් චක්‍රයේදී වැදගත් වන්නේ ඇයි?",
        "දිරාපත් නොවූ කාබනික ද්‍රව්‍ය විශාල ප්‍රමාණයක් ගබඩා කර ඇති බැවින් ඒවා වියළා ගිනි තැබූ විට අතිවිශාල කාබන් ඩයොක්සයිඩ් ප්‍රමාණයක් වායුගෝලයට මුදා හැරෙන නිසා", "ඒවා කාන්තාර වැලි බැවින්", "ඒවා තුළ යපස් ඇති බැවින්", "ඒවා රන් නිපදවන බැවින්",
        "ඉන්දුනීසියාවේ හා සයිබීරියාවේ පීට් තෙත් බිම් ආරක්ෂා කිරීම ගෝලීය දේශගුණික ස්ථායීතාවයට ඉතා වැදගත් වේ."),
      q(t, "ලෝකයේ 'ඛනිජ තෙල් කාන්දුවීම්' (Oil Spills - උදා: Exxon Valdez, Deepwater Horizon) සාගර සම්පත්වලට විනාශකාරී වන්නේ කෙසේද?",
        "ජලය මත තෙල් තට්ටුවක් පැතිරී සූර්යාලෝකය හා ඔක්සිජන් අවහිර වීම, මුහුදු පක්ෂීන්ගේ පිහාටු හා මසුන්ගේ කරමල් වැසී මියයාම හා දිගුකාලීනව ආහාර දාම දූෂණය වීම", "සාගරයේ උෂ්ණත්වය -50°C වීම", "කොරල් වේගයෙන් වැඩීම", "ලුණු රසය නැති වීම",
        "තෙල් නැව් හා සාගර පතුලේ කැණීම් සඳහා දැඩි ආරක්ෂක ප්‍රමිතීන් පැනවීම අත්‍යවශ්‍ය වේ."),
      q(t, "'ජල පරිභෝජන ගැටුම්' (Transboundary Water Conflicts) ඇති වන්නේ කුමන භූගෝලීය තත්ත්වයක් යටතේද?",
        "එක් ප්‍රධාන ගංගාවක් (නයිල්, මීකොං, ටයිග්‍රීස්-යුප්‍රටීස්, ඉන්දු) රටවල් කිහිපයක් හරහා ගලා යන විට ඉහළ රටවල් විශාල වේලි බැඳීමෙන් පහළ රටවලට ලැබෙන ජලය අඩු වේ යැයි ගැටුම් ඇතිවීම", "ගංගාවක් එක් කුඩා දිවයිනක පමණක් තිබීම", "වැසි සෑම දිනකම වැසීම", "සාගරයේ මසුන් සිටීම",
        "නයිල් ගඟේ ඉතියෝපියාවේ GERD වේල්ල සහ ඊජිප්තුව අතර සාකච්ඡා මීට ප්‍රධාන උදාහරණයකි."),
      q(t, "වනජීවී සම්පත් ආරක්ෂා කිරීම සඳහා 'ජෛව කොරිඩෝ / වන අලි මාරු මංකඩ' (Wildlife Corridors) පවත්වාගැනීම වැදගත් වන්නේ ඇයි?",
        "වෙන් වී ඇති කුඩා වනාන්තර කොටස් එකිනෙකට සම්බන්ධ කර අලින් හා වන සතුන්ට ආහාර, ජලය හා අභිජනනය සඳහා ආරක්ෂිතව සංක්‍රමණය වීමට ඉඩ දී මිනිස්-වනඅලි ගැටුම අඩු කිරීමට", "වන සතුන් කොටු කර තැබීමට", "අධිවේගී මාර්ග වැඩි කිරීමට", "වනාන්තර කැබලි කිරීමට",
        "ශ්‍රී ලංකාවේ වියළි කලාපයේ මිනිස්-අලි ගැටුම (Human-Elephant Conflict) විසඳීමට සාම්ප්‍රදායික අලි මංකඩ සංරක්ෂණය අත්‍යවශ්‍ය වේ."),
      q(t, "විකල්ප බලශක්ති ප්‍රභව අතර 'පොම්ප-ගබඩා ජල විදුලිය' (Pumped-Storage Hydroelectricity) ක්‍රියාත්මක වන්නේ කෙසේද?",
        "විදුලි ඉල්ලුම අඩු වේලාවන්හිදී අතිරික්ත සූර්ය/සුළං විදුලියෙන් පහළ ජලාශයේ ජලය ඉහළ ජලාශයට පොම්ප කර, ඉල්ලුම වැඩි උච්ච වේලාවන්හිදී එය පහළට මුදා හැර විදුලිය නිපදවීම", "මුහුදු ජලය වාෂ්ප කිරීම", "ගල් අඟුරු පොම්ප කිරීම", "භූගත තෙල් ළිං පිරවීම",
        "මෙය යෝධ 'ජල බැටරියක්' මෙන් ක්‍රියා කර ජාතික විදුලිබල පද්ධතිය ස්ථායී කරයි."),
      q(t, "'ජෛව ඉන්ධන' (Biofuels - Bioethanol හා Biodiesel) නිපදවීම සඳහා බහුලවම භාවිත කරන කෘෂිකාර්මික බෝග මොනවාද?",
        "බඩඉරිඟු, උක්, සෝයා බෝංචි, තෙල් පාම් (Oil Palm) සහ ජැට්‍රෝපා", "යපස් සහ තඹ", "තිරිඟු පිදුරු පමණි", "මිනිරන්",
        "බ්‍රසීලය උක් ගස්වලින් නිපදවන ජෛව එතනෝල් මගින් මෝටර් රථ ඉන්ධන අවශ්‍යතාවයෙන් විශාල කොටසක් සපුරා ගනී."),
      q(t, "ආහාර බෝග වගා කරන ඉඩම් මහා පරිමාණයෙන් 'ජෛව ඉන්ධන' වගාවන් සඳහා යොදා ගැනීමේදී ඇතිවන ප්‍රධාන සදාචාරාත්මක හා ආර්ථික ගැටලුව කුමක්ද?",
        "'ආහාර හා ඉන්ධන අතර ගැටුම' (Food vs Fuel) ඇතිවී ආහාර මිල ඉහළ යාම හා වනාන්තර හෙළි කිරීම (උදා: තෙල් පාම් සඳහා ඉන්දුනීසියානු වැසි වනාන්තර)", "ඉන්ධන නොමිලේ ලැබීම", "ආහාර අතිරික්තය", "වනාන්තර වර්ධනය වීම",
        "එබැවින් කෘෂිකාර්මික අපද්‍රව්‍ය හා ඇල්ගී (Algae) වලින් නිපදවන දෙවන/තෙවන පරම්පරාවේ ජෛව ඉන්ධන කෙරෙහි අවධානය යොමු වී ඇත."),
      q(t, "'OPEC' (Organization of the Petroleum Exporting Countries) සංවිධානයේ ප්‍රධාන අරමුණ කුමක්ද?",
        "සාමාජික රටවල ඛනිජ තෙල් නිෂ්පාදන ප්‍රමාණය සීමා කිරීම හෝ වැඩි කිරීම මගින් ලෝක වෙළඳපොළේ තෙල් මිල හා සැපයුම ස්ථාවරව පවත්වා ගැනීම", "සූර්ය පැනල බෙදා හැරීම", "වනාන්තර ආරක්ෂා කිරීම", "මිරිදිය ජලය විකිණීම",
        "1960 දී බැග්ඩෑඩ්හිදී ආරම්භ වූ OPEC හි මූලස්ථානය වියානා නගරයේ පිහිටා ඇත."),
      q(t, "'තාර වැලි' (Tar Sands / Oil Sands - කැනඩාවේ ඇල්බර්ටා) සහ 'ෂේල් තෙල්' (Shale Oil - ඇමරිකාව) වැනි සම්ප්‍රදායික නොවන පොසිල ඉන්ධන නිස්සාරණය විවේචනයට ලක්වන්නේ ඇයි?",
        "සාමාන්‍ය තෙල් ළිංවලට වඩා විශාල ජලය, බලශක්තිය හා රසායනික ද්‍රව්‍ය වැය වීමත්, විශාල වනාන්තර භූමි හා භූගත ජලය දූෂණය වීමත්", "ඒවායේ කිසිදු ශක්තියක් නැති නිසා", "ඒවා පුනර්ජනනීය නිසා", "ඒවා නොමිලේ ගලන නිසා",
        "හයිඩ්‍රොලික් පැලීම (Fracking) මගින් ෂේල් වායු නිස්සාරණයේදී කුඩා භූ කම්පන හා ජල දූෂණ අවදානම්ද වාර්තා වී ඇත."),
      q(t, "ස්වාභාවික සම්පත් අතර 'පොස්පරස්' (Phosphorus) සහ 'පොටෑසියම්' (Potash) ගෝලීය ආහාර නිෂ්පාදනයට අත්‍යවශ්‍ය වන්නේ ඇයි?",
        "නයිට්‍රජන් සමඟ එක්ව රසායනික පොහොරවල (NPK) ප්‍රධාන පෝෂක මූලද්‍රව්‍ය ලෙස බෝග වර්ධනයට හා අස්වැන්නට නැතිවම බැරි බැවින්", "විදුලි රැහැන් සෑදීමට", "රෙදි වියීමට", "වාහන ටයර් සෑදීමට",
        "මොරොක්කෝව ලෝකයේ විශාලතම පොස්පේට් සංචිතය දරන අතර කැනඩාව හා බෙලාරුස් පොටෑෂ් නිෂ්පාදනයේ ප්‍රමුඛයන් වේ."),
      q(t, "'විදුලි රථ' (Electric Vehicles) සඳහා භාවිත කරන දුර්ලභ පස් මූලද්‍රව්‍ය (Rare Earth Elements - Neodymium, Dysprosium) ගෝලීය සැපයුමේ ප්‍රධාන ආධිපත්‍යය දරන රට කුමක්ද?",
        "චීනය (ලෝකයේ සැකසීමේ හා පිරිපහදු කිරීමේ ධාරිතාවයෙන් ~80%+ පාලනය කරයි)", "නෝර්වේ", "නේපාලය", "නවසීලන්තය",
        "සුළං ටර්බයින චුම්භක, ලේසර්, ඉලෙක්ට්‍රොනික තිර හා EV මෝටර සඳහා මෙම මූලද්‍රව්‍ය අත්‍යවශ්‍ය වේ."),
      q(t, "'ස්වාභාවික රබර්' (Natural Rubber) කෘත්‍රිම රබර්වලින් (Synthetic Rubber) වෙනස් වන ප්‍රධාන සම්පත් ලක්ෂණය කුමක්ද?",
        "ස්වාභාවික රබර් Hevea brasiliensis ගසින් ලැබෙන පුනර්ජනනීය ජෛව සම්පතක් වන අතර කෘත්‍රිම රබර් ඛනිජ තෙල් (පෙට්‍රෝ-රසායනික) ආශ්‍රිතව නිපදවන පුනර්ජනනීය නොවන නිෂ්පාදනයකි", "දෙකම ඛනිජ තෙල් වලින් සාදයි", "ස්වාභාවික රබර් ගල් අඟුරුවලින් ලැබේ", "වෙනසක් නැත",
        "තායිලන්තය, ඉන්දුනීසියාව, වියට්නාමය හා ශ්‍රී ලංකාව ස්වාභාවික රබර් නිපදවන නිවර්තන රටවල් අතර වේ."),
      q(t, "'කොරල්පර' (Coral Reefs) 'සාගරයේ වැසි වනාන්තර' ලෙස හඳුන්වනු ලබන්නේ කුමන හේතුව නිසාද?",
        "සාගර මතුපිටින් 1% කටත් වඩා අඩු ප්‍රදේශයක් ආවරණය කළද සමස්ත සාගර ජීවී විශේෂවලින් ~25% කට වාසභූමි හා ආහාර සපයන බැවින්", "ඒවා මිරිදිය ගංගාවල වැඩෙන බැවින්", "ඒවායේ විශාල ගස් ඇති බැවින්", "ඒවා සීතල ධ්‍රැව මුහුදේ ඇති බැවින්",
        "සාගර උෂ්ණත්වය ඉහළ යාම නිසා ඇතිවන 'කොරල් විරංජනය' (Coral Bleaching) හික්කඩුව හා මහා බාධක පරය (Great Barrier Reef) වැනි පද්ධතිවලට තර්ජනයක් වී ඇත."),
      q(t, "'භූගත ජල දූෂණය' (Groundwater Contamination) මතුපිට ගංගා දූෂණයට වඩා භයානක හා පිරිසිදු කිරීමට අපහසු වන්නේ ඇයි?",
        "භූගත ජලය ඉතා මන්දගාමීව ගලා යන බැවින් රසායනික පොහොර, පළිබෝධනාශක, අසූචි හා බැර ලෝහ දශක ගණනාවක් පුරා පාෂාණ ස්තර තුළ රැඳී පවතින බැවින්", "භූගත ජලය කිසිදා බීමට නොගන්නා නිසා", "භූගත ජලය තප්පරයෙන් වාෂ්ප වන නිසා", "ගංගා පිරිසිදු කිරීම කළ නොහැකි නිසා",
        "කෘෂිකාර්මික ප්‍රදේශවල නයිට්‍රේට් දූෂණය හා බැර ලෝහ එක්රැස් වීම බරපතල සෞඛ්‍ය ගැටලු ඇති කරයි."),
      q(t, "'පරිසර පද්ධති සේවා' (Ecosystem Services) යනු කුමක්ද?",
        "පිරිසිදු ජලය, පරාගණය, පාංශු සාරවත්භාවය, දේශගුණ නියාමනය හා ගංවතුර පාලනය වැනි ස්වාභාවික පරිසරයෙන් මනුෂ්‍යයාට නොමිලේ ලැබෙන අත්‍යවශ්‍ය ප්‍රතිලාභ", "පෞද්ගලික සමාගම් විකුණන ජල බෝතල්", "කර්මාන්තශාලා නිෂ්පාදන", "වාහන අලුත්වැඩියා සේවා",
        "මී මැස්සන්ගේ පරාගණ සේවාව බිඳ වැටුණහොත් ගෝලීය පලතුරු හා එළවළු නිෂ්පාදනය දැඩි ලෙස කඩා වැටෙනු ඇත."),
      q(t, "'දැව සඳහා අධික ලෙස ගස් කැපීම' පාලනය කරන 'තිරසාර වන කළමනාකරණයේ' (Sustainable Forestry) මූලික පියවර මොනවාද?",
        "වරණීය ගස් කැපීම (Selective Logging), නැවත වන වගාව (Reforestation) සහ සහතික කළ දැව (FSC Certified Timber) භාවිතය", "සම්පූර්ණ වනාන්තරයම ගිනි තැබීම", "පැළ සිටුවීම තහනම් කිරීම", "ගංගා හරවා වනාන්තර වියළීම",
        "නීතිවිරෝධී දැව ජාවාරම වැළැක්වීම සඳහා චන්ද්‍රිකා තාක්ෂණයෙන් වන ආවරණය නිරීක්ෂණය කෙරේ."),
      q(t, "ඛනිජ සම්පත් භූගෝල විද්‍යාවේ 'සම්පත් ශාපය' (Resource Curse / Paradox of Plenty) යන්නෙන් අදහස් කරන්නේ කුමක්ද?",
        "තෙල්, දියමන්ති හෝ කොබෝල්ට් වැනි වටිනා ස්වාභාවික සම්පත් බහුල සමහර රටවල් දූෂණය, සිවිල් ගැටුම් හා අනෙකුත් අංශ නොසලකා හැරීම නිසා අඩු ආර්ථික සංවර්ධනයක් පෙන්නුම් කිරීම", "සම්පත් ඇති සෑම රටක්ම ධනවත් වීම", "කෘෂිකර්මය වැඩිවීම", "වර්ෂාව නතර වීම",
        "නෝර්වේ රාජ්‍යය සිය තෙල් ආදායම ස්වෛරී ධන අරමුදලක තැන්පත් කර අධ්‍යාපනය හා සුබසාධනය සඳහා යොදමින් 'සම්පත් ශාපය' ජය ගත් ආදර්ශමත් රටකි."),
      q(t, "'ස්වාභාවික වරායන්' සම්පතක් ලෙස සලකන විට, ශ්‍රී ලංකාවේ ත්‍රිකුණාමලය වරාය ලොව හොඳම ස්වාභාවික ගැඹුරු වරායන්ගෙන් එකක් වීමට හේතුව කුමක්ද?",
        "ගොඩබිමින් ආරක්ෂිතව වටවූ ගැඹුරු ජල තටාකයක් (මහවැලි භූ විභේදන කැනියමක බලපෑම) පැවතීම නිසා විශාල නැව්වලට කුණාටු වලින් ආරක්ෂිතව නැංගුරම් ලෑමට හැකිවීම", "එය මිරිදිය විලක් වීම", "එහි ජල ගැඹුර මීටර් 1 ක් පමණ වීම", "එය කඳු මුදුනක පිහිටීම",
        "ඕනෑම මෝසම් කාලයකදී ආරක්ෂිත නැංගුරම් පහසුකම් සැපයීමට ත්‍රිකුණාමලය වරාය සමත් වේ."),
      q(t, "'පෘථිවියේ ඛනිජ තෙල් සංචිත කවදා හෝ අවසන් වීම' හෙවත් 'උච්ච තෙල්' (Peak Oil) සංකල්පය අපට උගන්වන ප්‍රධාන පාඩම කුමක්ද?",
        "පොසිල ඉන්ධන සීමිත සම්පතක් බැවින් ප්‍රවාහනය, විදුලි ජනනය හා කර්මාන්ත ක්‍රමයෙන් පුනර්ජනනීය හරිත බලශක්ති වෙත සංක්‍රමණය විය යුතු බව", "තෙල් අනන්තවත් ඇති බව", "ගස් කැපිය යුතු බව", "විදුලිය අවශ්‍ය නොවන බව",
        "වර්තමානයේ දේශගුණික විපර්යාස අවම කිරීමේ අවශ්‍යතාව නිසා තෙල් අවසන් වීමටත් පෙර පොසිල ඉන්ධන භාවිතය අඩු කිරීමට ලෝකය උත්සාහ කරයි."),
      q(t, "'භූගත පාෂාණ කාබන් ගබඩා කිරීම' (Carbon Capture and Storage - CCS) ක්‍රමයේදී සිදු කරන්නේ කුමක්ද?",
        "බලාගාර හා කර්මාන්තශාලාවලින් පිටවන කාබන් ඩයොක්සයිඩ් (CO2) වායුගෝලයට මුදා නොහැර අල්ලා ගෙන පොළොව යට ගැඹුරු භූ විද්‍යාත්මක ස්තරවල ස්ථිරව තැන්පත් කිරීම", "CO2 වායුගෝලයට පොම්ප කිරීම", "ගස් කපා පිළිස්සීම", "සාගරය රත් කිරීම",
        "කෙසේ වෙතත් CCS තාක්ෂණය ඉතා මිල අධික බැවින් පළමුව පුනර්ජනනීය බලශක්තියට මාරු වීම වඩාත් ඵලදායී වේ."),
      q(t, "'බහුල සම්පත්' (Ubiquitous Resources) සහ 'ස්ථානගත සම්පත්' (Localized Resources) අතර වෙනස කුමක්ද?",
        "වාතය හා සූර්යාලෝකය සෑම තැනම පවතින බහුල සම්පත් වන අතර යපස්, මැණික් හා බොරතෙල් නිශ්චිත භූගෝලීය ස්ථානවල පමණක් පවතින ස්ථානගත සම්පත් වේ", "මැණික් සෑම තැනම ඇත", "වාතය පොළොව යට පමණක් ඇත", "වෙනසක් නැත",
        "ස්ථානගත සම්පත් අසමාන ලෙස බෙදී තිබීම ජාත්‍යන්තර වෙළඳාමට හා භූ-දේශපාලනික තරඟකාරිත්වයට මග පාදයි."),
      q(t, "ජල සම්පත් සංරක්ෂණයේදී 'අළු ජලය' (Greywater) නැවත භාවිතය යන්නෙන් අදහස් කරන්නේ කුමක්ද?",
        "වැසිකිළි අපද්‍රව්‍ය රහිතව ස්නානය, අත් සේදීම හා රෙදි සේදීමෙන් ඉවතලන ජලය පෙරා ගෙවතු වගාව, උද්‍යාන ජල සැපයුම හා වැසිකිළි සේදීම සඳහා නැවත යොදා ගැනීම", "වර්ණවත් කළ බීම ජලය", "මුහුදු ජලය බීම", "කර්මාන්තශාලා රසායනික විෂ ජලය",
        "අළු ජලය ප්‍රතිචක්‍රීකරණය කිරීමෙන් නාගරික නිවාස හා හෝටල්වල පානීය ජල නාස්තිය 30%–40% කින් අඩු කළ හැකිය."),
      q(t, "'සූර්ය පැනල සමඟ කෘෂිකර්මය' (Agrivoltaics) යන නව තිරසාර සම්පත් සංකල්පයේ වාසිය කුමක්ද?",
        "එකම බිම් කැබැල්ලේ උසින් සවි කළ සූර්ය පැනලවලින් විදුලිය නිපදවන අතරම ඊට යටින් ඇති අර්ධ සෙවණේ එළවළු වගා කිරීමෙන් ජල වාෂ්පීභවනය අඩු කර ඉඩම් ඵලදායිතාව දෙගුණ කිරීම", "සියලු කෘෂි ඉඩම් කොන්ක්‍රීට් කිරීම", "සූර්ය පැනල මත වී වැපිරීම", "විදුලියෙන් ගස් කැපීම",
        "ඉඩම් හිඟ රටවල ආහාර හා බලශක්ති සුරක්ෂිතතාව එකවර ළඟා කර ගැනීමට මෙය උපකාරී වේ."),
      q(t, "'න්‍යෂ්ටික විලයනය' (Nuclear Fusion) අනාගත බලශක්ති විප්ලවයක් ලෙස විද්‍යාඥයන් බලාපොරොත්තු තබන්නේ ඇයි?",
        "සූර්යයා තුළ මෙන් හයිඩ්‍රජන් පරමාණු විලයනයෙන් අසීමිත පිරිසිදු ශක්තියක් ලබාගත හැකි වීමත්, දිගුකාලීන විකිරණශීලී අපද්‍රව්‍ය හා හරිතාගාර වායු නොමැති වීමත්", "එය ගල් අඟුරු දහනය කරන නිසා", "එය ඉතා පහසුවෙන් නිවසේදී කළ හැකි නිසා", "එය ඛනිජ තෙල් නිපදවන නිසා",
        "ප්‍රංශයේ ITER ව්‍යාපෘතිය වැනි ජාත්‍යන්තර පර්යේෂණ මගින් වාණිජ න්‍යෂ්ටික විලයන බලාගාර සංවර්ධනය කිරීමට උත්සාහ කෙරේ."),
      q(t, "'ශ්‍රී ලංකාවේ මැණික් සම්පත' (රත්නපුර, ඇලහැර, බළන්ගොඩ, කතරගම) බොහෝ විට හමුවන්නේ කුමන භූ විද්‍යාත්මක තැන්පතුවලින්ද?",
        "ගංගා නිම්න හා පුරාණ ගං පතුල්වල තැන්පත් වූ දියළු බොරළු ස්තර ('ඉල්ලම්') තුළින්", "ගිනිකඳු ආවාට තුළින්", "කොරල්පර තුළින්", "වැලි කඳු තුළින්",
        "දැඩි තාපය හා පීඩනය යටතේ මව් පාෂාණවල සෑදුණු නිල් මැණික්, පද්මරාග හා කණක මැණික් ඛාදනය වී ගංගා දියළු තැන්පතුවල එක්රැස් වී ඇත."),
      q(t, "ඛනිජ තෙල් සම්පත නොමැති වුවද, ලෝකයේ ප්‍රධාන තෙල් පිරිපහදු හා නැව් ඉන්ධන සැපයුම් මධ්‍යස්ථානයක් ලෙස 'සිංගප්පූරුව' දියුණු වීමට හේතුව කුමක්ද?",
        "නැගෙනහිර ආසියාව හා මැදපෙරදිග යා කරන මලක්කා සමුද්‍ර සන්ධියේ උපායමාර්ගික නාවික පිහිටීම සහ උසස් වරාය යටිතල පහසුකම්", "සිංගප්පූරුවේ විශාල තෙල් ළිං තිබීම", "විශාල ගල් අඟුරු පතල් තිබීම", "ගොවිපළවල් තිබීම",
        "ස්වාභාවික ඛනිජ සම්පත් හිඟ වුවද භූගෝලීය පිහිටීම හා මානව සම්පත ප්‍රබල ආර්ථික සම්පතක් බවට පත් කළ හැකිය."),
      q(t, "'වායු බලශක්ති හා හරිත වනාන්තර සම්පත' එකට ආරක්ෂා කරන 'ගොවිපළ කසළ ජෛව වායු ඒකක' (Biogas Units) ග්‍රාමීය ප්‍රජාවට ප්‍රයෝජනවත් වන්නේ කෙසේද?",
        "දර කැපීම අඩු කර වනාන්තර ආරක්ෂා කිරීම, ගෘහස්ථ දුමාරයෙන් ඇතිවන පෙනහළු රෝග වැළැක්වීම සහ උසස් කාබනික පොහොර නිපදවීම", "වනාන්තර කැපීම වැඩි කිරීම", "මීතේන් වායුව නිකරුණේ පිට කිරීම", "ජලය දූෂණය කිරීම",
        "එසේම කසළ දිරාපත් වීමෙන් වායුගෝලයට එක්වන ප්‍රබල මීතේන් වායුව ඉන්ධනයක් ලෙස දහනය කිරීමෙන් දේශගුණික බලපෑමද අඩු වේ."),
      q(t, "'සමුද්‍රීය ඛනිජ ගවේෂණය' (Deep-Sea Mining) පිළිබඳව සමුද්‍ර විද්‍යාඥයන් දැඩි අවවාද නිකුත් කරන්නේ ඇයි?",
        "සාගර පතුලේ බහු-ලෝහ ගැටිති (Polymetallic Nodules) කැණීමෙන් ඉතා සෙමින් වර්ධනය වන ගැඹුරු සාගර පරිසර පද්ධති හා දුර්ලභ ජීවීන් සදාකාලිකව විනාශ විය හැකි බැවින්", "මුහුදු ජලය ගොඩබිමට ගලන බැවින්", "සාගරයේ කිසිදු ජීවියෙකු නොමැති බැවින්", "ඛනිජ ලෝහ දියවන බැවින්",
        "විදුලි බැටරි සඳහා කොබෝල්ට් හා නිකල් ලබා ගැනීමට ගැඹුරු මුහුද කැණීම වෙනුවට බැටරි ප්‍රතිචක්‍රීකරණය වැඩි කිරීම වඩා ආරක්ෂිත බව පරිසරවේදීන් පවසයි."),
      q(t, "'භූගත පතල් කැණීමේදී' (Underground / Shaft Mining) කම්කරුවන් මුහුණ දෙන ප්‍රධාන භෞතික හා සෞඛ්‍ය අවදානම් මොනවාද?",
        "උමං කඩා වැටීම, මීතේන් වායු පිපිරීම්, ගල් අඟුරු හා සිලිකා දූවිල්ල නිසා ඇතිවන පෙනහළු රෝග (Silicosis) සහ ඉහළ භූගත උෂ්ණත්වය", "හිරු රශ්මිය වැඩි වීම", "හිම කුණාටු", "මුහුදු රළ ගැසීම",
        "නවීන පතල්වල වාතාශ්‍ර පද්ධති, ගෑස් සංවේදක හා ස්වයංක්‍රීය යන්ත්‍ර මගින් මෙම අවදානම් අවම කෙරේ."),
      q(t, "'ශ්‍රී ලංකාවේ කොග්ගල, හලාවත හා හම්බන්තොට' ආශ්‍රිතව වගා කරනු ලබන හෝ නෙළනු ලබන ප්‍රධාන ස්වාභාවික ඛනිජ හා ජීව සම්පත කුමක්ද? (හම්බන්තොට මහ ලේවාය ආශ්‍රිතව)",
        "මුහුදු ලුණු (Solar Evaporation Salt) හා කලපු ධීවර සම්පත්", "ගල් අඟුරු", "රොක් පොස්පේට්", "ඇස්බැස්ටස්",
        "වියළි දේශගුණය, අඩු වර්ෂාපතනය, තද සූර්ය රශ්මිය හා නොගැඹුරු කලපු තැනිතලා ලුණු ලේවායන් සඳහා අත්‍යවශ්‍ය වේ."),
      q(t, "'ජල කාන්දු පාලනය' (Leakage Control) නාගරික ජල සම්පාදන පද්ධතිවලදී 'ආදායම් නොලබන ජලය' (Non-Revenue Water) අඩු කිරීමට වැදගත් වන්නේ ඇයි?",
        "පිරිපහදු කර පොම්ප කරන පිරිසිදු පානීය ජලයෙන් 25%–40% ක් පමණ පැරණි බිඳුණු නළ මාර්ග හරහා අපතේ යාම වැළැක්වීමෙන් විශාල ජලය හා බලශක්ති ඉතිරියක් ලැබෙන බැවින්", "වැසි වැඩි කිරීමට", "ජලය ලවණ කිරීමට", "නළ මාර්ග ගැලවීමට",
        "අලුතින් ජලාශ තැනීමට පෙර පවතින නළ පද්ධතිවල ජල කාන්දු අවම කිරීම වඩාත් ලාභදායී ජල සුරක්ෂිතතා පියවරකි."),
      q(t, "ස්වාභාවික බලශක්ති ප්‍රභව අතර 'පොසිල ඉන්ධන සහනාධාර ඉවත් කර හරිත බලශක්තියට සහන දීම' රජයන් විසින් සලකා බලන්නේ ඇයි?",
        "කාබන් විමෝචනය අඩු කිරීම, වායු දූෂණය නිසා ඇතිවන සෞඛ්‍ය වියදම් පහත හෙළීම සහ රටේ දේශීය පුනර්ජනනීය බලශක්ති ස්වාධීනත්වය ගොඩනැගීමට", "සූර්ය පැනල මිල ඉහළ දැමීමට", "තෙල් ආනයනය වැඩි කිරීමට", "විදුලිය භාවිතය නැවැත්වීමට",
        "කාලගුණික විපර්යාස අවම කිරීමේ පැරිස් ගිවිසුම් ඉලක්ක සපුරාලීමට මෙම ප්‍රතිපත්ති උපකාරී වේ."),
      q(t, "'ජෛව විවිධත්ව සංරක්ෂණය' සඳහා 'ජාතික උද්‍යාන' (National Parks - උදා: යාල, විල්පත්තු) සහ 'දැඩි ස්වභාව රක්ෂිත' (Strict Natural Reserves - උදා: රිටිගල, හක්ගල) අතර වෙනස කුමක්ද?",
        "ජාතික උද්‍යාන පරිසර හිතකාමී සංචාරකයන්ට නැරඹීමට විවෘත වන අතර දැඩි ස්වභාව රක්ෂිතවලට විද්‍යාත්මක පර්යේෂණ සඳහා විශේෂ අවසරයකින් තොරව මහජනතාවට ඇතුළු වීම තහනම් වේ", "දෙකම ක්‍රීඩා පිටිය", "දැඩි රක්ෂිත තුළ හෝටල් ඉදි කළ හැකිය", "වෙනසක් නැත",
        "මෙමගින් වඩාත් සංවේදී ආවේණික ශාක හා සත්ත්ව ප්‍රජාවන්ට උපරිම ආරක්ෂාව සැපයේ."),
      q(t, "'සාගර තරංග හා සාගර තාප බලශක්තිය' (Wave Energy & OTEC - Ocean Thermal Energy Conversion) පර්යේෂණ මට්ටමේ පැවතියද නිවර්තන දූපත් රටවලට වැදගත් වන්නේ ඇයි?",
        "නිවර්තන සාගරවල මතුපිට උණුසුම් ජලය (26–28°C) හා ගැඹුරු සීතල ජලය (4–5°C) අතර ඉහළ උෂ්ණත්ව වෙනස මගින් දිවා රෑ දෙකෙහිම අඛණ්ඩ විදුලිය නිපදවිය හැකි බැවින්", "හිම දිය කිරීමට", "සාගරය කැටි කිරීමට", "කාන්තාර ඇති කිරීමට",
        "වටේටම ගැඹුරු සාගරය පිහිටි ශ්‍රී ලංකාව වැනි දිවයිනකට අනාගතයේදී සාගර බලශක්ති තාක්ෂණ ඉතා වැදගත් විභවයක් වේ."),
      q(t, "'කෘෂිකාර්මික අපද්‍රව්‍ය හා සතුන්ගේ පොහොර' වලට අමතරව 'ලිපි ද්‍රව්‍ය, කාඩ්බෝඩ් හා වීදුරු' ප්‍රතිචක්‍රීකරණය කිරීමෙන් ඉතිරි වන ප්‍රධාන ස්වාභාවික සම්පත් මොනවාද?",
        "වනාන්තර ගස්, ජලය, සිලිකා වැලි සහ බලශක්තිය", "යුරේනියම් සහ ප්ලූටෝනියම්", "රන් සහ මැණික්", "ඛනිජ තෙල් පමණි",
        "කඩදාසි ටොන් එකක් ප්‍රතිචක්‍රීකරණය කිරීමෙන් වැඩුණු ගස් 17 ක් පමණ සහ ජලය ලීටර් 26,000 ක් පමණ ඉතිරි වේ."),
      q(t, "'මුහුදු බඩ ලවණ ජලය ආක්‍රමණය' (Saltwater Intrusion) වැළැක්වීම සඳහා වෙරළබඩ භූගත ජල කළමනාකරණයේදී ගත යුතු ප්‍රධාන පියවර කුමක්ද?",
        "වෙරළට ආසන්නව අධික ලෙස නළ ළිං මගින් භූගත ජලය පොම්ප කිරීම සීමා කර වැසි ජලය පසට උරා ගැනීම වැඩි කිරීම", "මුහුදු ජලය ළිංවලට පොම්ප කිරීම", "සියලු වැව් වසා දැමීම", "කඩොලාන ඉවත් කිරීම",
        "මිරිදිය ජල පීඩනය අඩු වූ විට ඊට යටින් ඇති ලවණ ජල තලය ළිංවලට ඇතුළු වී පානීය ජලය හා වගා බිම් විනාශ කරයි."),
      q(t, "'ඛනිජ සම්පත් ආදේශනය' (Resource Substitution) යන්නෙන් අදහස් කරන්නේ කුමක්ද?",
        "හිඟ හෝ මිල අධික ක්ෂය වන සම්පතක් වෙනුවට වෙනත් සුලභ හෝ පරිසර හිතකාමී ද්‍රව්‍යයක් භාවිත කිරීම (උදා: තඹ කේබල් වෙනුවට ෆයිබර් ඔප්ටික් වීදුරු තන්තු)", "සම්පත් විසි කිරීම", "සියලු කම්හල් වැසීම", "එකම ඛනිජය දෙවරක් ගැනීම",
        "තාක්ෂණික නවෝත්පාදන මගින් හිඟ ලෝහ මත යැපීම අඩු කිරීමට සම්පත් ආදේශනය උපකාරී වේ."),
      q(t, "ලෝකයේ 'පළමු ජාතික උද්‍යානය' වන ඇමරිකාවේ යෙලෝස්ටෝන් (Yellowstone - 1872) පිහිටුවීම ස්වාභාවික සම්පත් ඉතිහාසයේ සුවිශේෂී වන්නේ ඇයි?",
        "ස්වාභාවික භූ දර්ශන, ගීසර හා වනජීවීන් වාණිජ සූරාකෑමෙන් ආරක්ෂා කර අනාගත පරපුර සඳහා රාජ්‍ය නීතියෙන් රක්ෂිත කළ ලොව ප්‍රථම මහා ආදර්ශය වීම", "එහි විශාල කර්මාන්තශාලා ඉදිකළ බැවින්", "එහි තෙල් පතල් කැණීම් කළ බැවින්", "එය ගුවන්තොටුපළක් වූ බැවින්",
        "මින් පසු ලොව පුරා රටවල් රැසක් සිය වන සම්පත් හා ජෛව විවිධත්වය රැක ගැනීමට ජාතික උද්‍යාන ජාල පිහිටුවීය."),
      q(t, "'ජල විදුලි ජලාශ පතුලේ රොන්මඩ තැන්පත් වීම' (Reservoir Siltation) බලශක්ති හා ජල සම්පත්වලට බලපාන්නේ කෙසේද?",
        "ඉහළ ජල පෝෂකයේ පාංශු ඛාදනය නිසා ජලාශයේ රොන්මඩ පිරී ජල ධාරිතාව, විදුලි නිෂ්පාදනය හා වාරි ආයු කාලය ක්‍රමයෙන් අඩු වීම", "ජලාශයේ ගැඹුර වැඩි වීම", "විදුලි නිෂ්පාදනය දෙගුණ වීම", "ජලය පිරිසිදු වීම",
        "ශ්‍රී ලංකාවේ කොත්මලේ, වික්ටෝරියා හා රන්දෙණිගල ජලාශ රැක ගැනීමට මධ්‍යම කඳුකරයේ පාංශු සංරක්ෂණය අතිශයින් වැදගත් වේ."),
      q(t, "'ගොඩබිම් සුළං බලය' (Onshore Wind) පිහිටුවීමේදී භූගෝලීය වශයෙන් සලකා බලන ප්‍රධාන සාධක මොනවාද?",
        "වසර පුරා ස්ථාවර හා ප්‍රමාණවත් සුළං වේගය (තත්පරයට මීටර් 6+), ජාතික විදුලි ජාලයට ඇති සමීපතාව, පක්ෂි සංක්‍රමණ මාර්ග මගහැරීම හා නිවාසවලට ඇති දුර", "ගල් අඟුරු නිධි තිබීම", "වැසි වනාන්තර මැද පිහිටීම", "සුළඟ ශුන්‍ය වීම",
        "විවෘත වෙරළබඩ තැනිතලා, කඳු මුදුන් සහ කඳු දුර්ගවල සුළං ටර්බයිනවලින් ඉහළ කාර්යක්ෂමතාවයක් ලැබේ."),
      q(t, "ස්වාභාවික සම්පත් කළමනාකරණයේදී 'ප්‍රාථමික ප්‍රතිචක්‍රීකරණය' සහ 'උපචක්‍රීකරණය' (Upcycling) අතර වෙනස කුමක්ද?",
        "ප්‍රතිචක්‍රීකරණයේදී ද්‍රව්‍යයක් සමාන හෝ අඩු ගුණාත්මකභාවයෙන් යුත් භාණ්ඩයක් බවට පත් වන අතර Upcycling හිදී ඉවතලන ද්‍රව්‍ය වැඩි වටිනාකමකින් හා ගුණාත්මකභාවයකින් යුත් නව නිෂ්පාදනයක් බවට පත් කෙරේ", "දෙකම කසළ ගිනි තැබීමයි", "Upcycling යනු කසළ මුහුදට දැමීමයි", "වෙනසක් නැත",
        "උදාහරණයක් ලෙස ඉවතලන ප්ලාස්ටික් බෝතල් හෝ ටයර් කලාත්මක ගෘහ භාණ්ඩ හා සපත්තු නිපදවීමට යොදා ගැනීම."),
      q(t, "'නාගරික හරිත යටිතල පහසුකම්' (Green Infrastructure) ජල සම්පත් කළමනාකරණයට දායක වන්නේ කෙසේද?",
        "වැසි උද්‍යාන (Rain Gardens), පාරගම්‍ය පදික වේදිකා සහ තෙත් බිම් උද්‍යාන මගින් වැසි ජලය පෙරා පොළොවට උරා ගැනීමට සලස්වා භූගත ජලය පෝෂණය කිරීම", "සියලු පොළොව තාර දැමීම", "ගස් කපා දැමීම", "ජලය ඉවතට පොම්ප කිරීම පමණි",
        "චීනයේ 'ස්පොන්ජ් නගර' (Sponge Cities) සැලැස්ම මෙම ජල කළමනාකරණ ක්‍රමවේදයේ ප්‍රමුඛ උදාහරණයකි."),
      q(t, "'නාවික මාර්ග හා සාගර ඛනිජ' වලට අමතරව 'ලෝකයේ ප්‍රධාන සමුද්‍ර මත්ස්‍ය ධීවර කලාප' සෞම්‍ය හා උප-ධ්‍රැව අක්ෂාංශවල (ජපානය, උතුරු අත්ලාන්තික්, පේරු) බහුල වී ඇත්තේ ඇයි?",
        "උණුසුම් හා ශීත සාගර දියවැල් හමුවීම හෝ ගැඹුරු පෝෂක බහුල ජලය ඉහළට නැගීම (Upwelling) නිසා ප්ලවාංග (Plankton) බහුලව වැඩී මසුන් ආකර්ෂණය වන බැවින්", "සමකයේ ජලය ලුණු රහිත නිසා", "සීතල ජලයේ මසුන් පමණක් පිහිනන නිසා", "ගිනිකඳු නිසා",
        "පේරු වෙරළේ හම්බෝල්ට් ශීත දියවැලේ Upwelling ක්‍රියාවලිය ලොව විශාලතම ඇන්චෝවි මත්ස්‍ය කර්මාන්තයට පදනම සපයයි."),
      q(t, "ශ්‍රී ලංකාවේ 'මීතියාගොඩ' සහ 'බොරලැස්ගමුව/දෙදියවල' ප්‍රදේශ විශේෂිත වී ඇත්තේ පිඟන් හා වීදුරු කර්මාන්තයට අවශ්‍ය කුමන ඛනිජ සම්පත් සඳහාද?",
        "කේයෝලින් (Kaolin - සුදු මැටි) සහ බෝල් මැටි (Ball Clay) තැන්පතු", "යපස්", "තඹ", "ගල් අඟුරු",
        "වීදුරු කර්මාන්තයට අවශ්‍ය පිරිසිදු සිලිකා වැලි (Silica Sand) මාරවිල, නාත්තන්ඩිය හා අම්පාර ප්‍රදේශවල බහුලව හමුවේ."),
      q(t, "ශ්‍රී ලංකාවේ 'මාතලේ, නාඋල හා රත්නපුර' ප්‍රදේශවල හමුවන උසස් තත්ත්වයේ ක්වාර්ට්ස් (Vein Quartz - තිරිවාණා) ඛනිජය කුමන කර්මාන්ත සඳහා අපනයනය කෙරේද?",
        "සූර්ය පැනල සිලිකන්, ක්වාර්ට්ස් ඔරලෝසු, ප්‍රකාශ තන්තු (Optic Fibers), වීදුරු සහ සෙරමික් කර්මාන්ත", "රෙදි වියීම", "ධීවර දැල්", "ලුණු නිෂ්පාදනය",
        "ශ්‍රී ලංකාවේ 99% කට වඩා පිරිසිදු සිලිකා අඩංගු කිරි පැහැති තිරිවාණා ඛනිජයට ජාත්‍යන්තර ඉල්ලුමක් පවතී."),
      q(t, "ශ්‍රී ලංකාවේ ඉදි කර ඇති විශාලතම තාප ගල් අඟුරු විදුලි බලාගාරය වන 'ලක්විජය බලාගාරය' පිහිටා ඇත්තේ කොතැනද?",
        "පුත්තලම දිස්ත්‍රික්කයේ නොරොච්චෝලේ", "හම්බන්තොට", "මහනුවර", "යාපනයේ",
        "වෙරළාශ්‍රිතව පිහිටුවා ඇත්තේ ආනයනික ගල් අඟුරු බා ගැනීමේ පහසුව හා සිසිලන මුහුදු ජලය ලබා ගැනීම සඳහාය."),
      q(t, "'ස්වාභාවික වායු ද්‍රවකරණය' (LNG - Liquefied Natural Gas) ජාත්‍යන්තර බලශක්ති ප්‍රවාහනයේදී වැදගත් වන්නේ ඇයි?",
        "වායුව -162°C දක්වා සිසිල් කර ද්‍රව බවට පත් කිරීමෙන් පරිමාව 600 ගුණයකින් පමණ අඩු වන බැවින් නළ මාර්ග නොමැති විට විශේෂිත නැව්වලින් සාගර හරහා ප්‍රවාහනය කළ හැකි වීම", "එය ගල් අඟුරු බවට පත්වීම", "එය රත් වී පිපිරීම", "එය ජලය බවට පත්වීම",
        "කටාර්, ඔස්ට්‍රේලියාව හා ඇමරිකාව ලොව ප්‍රධාන LNG අපනයනකරුවන් අතර සිටී."),
      q(t, "'ජල විදුලි බලාගාර සංකීර්ණ' අතර ශ්‍රී ලංකාවේ කැලණි ගඟේ ඉහළ ද්‍රෝණියේ පිහිටි ලක්ෂපාන, විමලසුරේන්ද්‍ර, කැනියොන් සහ පොල්පිටිය බලාගාර සඳහා ජලය සපයන ප්‍රධාන ජලාශ දෙක මොනවාද?",
        "කාසල්රී (Castlereagh) සහ මාවුස්සාකැලේ (Maussakelle)", "සේනානායක සමුද්‍රය සහ උඩවලව", "පරාක්‍රම සමුද්‍රය සහ කලා වැව", "ලුණුගම්වෙහෙර සහ රන්ටැඹේ",
        "ලක්ෂපාන ජල විදුලි සංකීර්ණය ශ්‍රී ලංකාවේ පැරණිතම හා ප්‍රධානතම ජල විදුලි ජනන පද්ධතියකි."),
      q(t, "'කොත්මලේ, වික්ටෝරියා, රන්දෙණිගල සහ රන්ටැඹේ' යන මහා ජලාශ හතර ඉදිකර ඇත්තේ කුමන ප්‍රධාන ගංගාව හා එහි අතු ගංගා ආශ්‍රිතවද?",
        "මහවැලි ගඟ (කඩිනම් මහවැලි සංවර්ධන වැඩසටහන යටතේ)", "වලවේ ගඟ", "කළු ගඟ", "ගිං ගඟ",
        "මෙම ජලාශ විදුලිය නිපදවීමට මෙන්ම පොල්ගොල්ල හා මිනිපේ හරහා වියළි කලාපයේ කුඹුරු ලක්ෂ ගණනකට වාරි ජලය සැපයීමට යොදා ගනී."),
      q(t, "'ඛනිජ හා ලෝහ' වලින් 'තඹ' (Copper) නිෂ්පාදනයේදී ලෝපස්වල ලෝහ සාන්ද්‍රණය 1% කටත් වඩා අඩු වුවද කැණීම ලාභදායී වන්නේ කෙසේද?",
        "අතිවිශාල පරිමාණයෙන් විවෘත පතල් කැණීම, නවීන තලා වෙන් කිරීමේ තාක්ෂණය සහ බහුවිධ ඉලෙක්ට්‍රොනික/ඉදිකිරීම් ඉල්ලුම නිසා", "තඹ නොමිලේ ඉබේ පිරිසිදු වන නිසා", "සෑම රටකම තඹ තිබෙන නිසා", "වැසි ජලයෙන් තඹ හැදෙන නිසා",
        "එසේම කැණීමෙන් පසු ඉතිරි වන විශාල පාෂාණ කැබලි හා රසායනික රොන්මඩ (Mine Tailings) ආරක්ෂිතව ගබඩා කිරීම පාරිසරික අභියෝගයකි."),
      q(t, "'හරිතාගාර වායු විමෝචනය අවම කිරීමේදී' විදුලි ජනනයට යොදාගන්නා 'ගල් අඟුරු' සම්පත ක්‍රමයෙන් ඉවත් කිරීම (Coal Phase-out) ප්‍රමුඛ වන්නේ ඇයි?",
        "සියලු පොසිල ඉන්ධන අතරින් විදුලි ඒකකයක් නිපදවීමේදී වැඩිම CO2, සල්ෆර් ඩයොක්සයිඩ්, රසදිය හා සියුම් අංශු (PM2.5) පිට කරන්නේ ගල් අඟුරු වන බැවින්", "ගල් අඟුරු වලින් විදුලිය නොසෑදෙන නිසා", "ගල් අඟුරු අධික සීතල නිසා", "ගල් අඟුරු දියරයක් නිසා",
        "ජර්මනිය හා එක්සත් රාජධානිය වැනි රටවල් ගල් අඟුරු බලාගාර වසා දමා සුළං හා සූර්ය බලය වෙත මාරු වෙමින් සිටී."),
      q(t, "'දියමන්ති' (Diamonds) සම්පත භූගෝල විද්‍යාත්මකව ප්‍රධාන වශයෙන් හමුවන්නේ කුමන භූ විද්‍යාත්මක ආකෘති තුළද?",
        "පැරණි මහාද්වීපික පළිහවල ඇති ගැඹුරු ගිනිකඳු නළ වන 'කිම්බර්ලයිට් පයිප්ප' (Kimberlite Pipes) හා ඉන් සේදී ගිය දියළු තැන්පතුවල", "හුණුගල් ගුහාවල", "කොරල්පරවල", "ගල් අඟුරු ස්තරවල",
        "දකුණු අප්‍රිකාව, බොට්ස්වානා, රුසියාව හා කැනඩාව ලොව ප්‍රධාන ස්වාභාවික දියමන්ති නිෂ්පාදකයෝ වෙති."),
      q(t, "'ලේ ගැලූ දියමන්ති' (Conflict / Blood Diamonds) යන්නෙන් සම්පත් භූගෝල විද්‍යාවේ විස්තර කෙරෙන්නේ කුමක්ද?",
        "සන්නද්ධ කැරලිකරුවන් විසින් සිවිල් යුද්ධවලට මුදල් සැපයීම සඳහා බලහත්කාර ශ්‍රමය යොදා අවිධිමත්ව කැණීම් කර අලෙවි කරන දියමන්ති", "රතු පැහැති දියමන්ති", "ගිනිකඳු තුළ ඇති දියමන්ති", "කෘත්‍රිම දියමන්ති",
        "මෙය නැවැත්වීම සඳහා දියමන්ති වෙළඳාම සහතික කරන 'කිම්බර්ලි ක්‍රියාවලිය' (Kimberley Process) හඳුන්වා දෙන ලදී."),
      q(t, "ලෝකයේ 'පළමු වාණිජමය රසායනික හා ඉන්ධන බලශක්තිය' වූ 'දර හා අඟුරු' තවමත් අඩු ආදායම් රටවල මිලියන ගණනක් ජනතාව භාවිත කිරීම නිසා ඇතිවන ගැටලු මොනවාද?",
        "වනාන්තර හායනය, ගෘහස්ථ වායු දූෂණය නිසා කාන්තාවන් හා ළමුන්ට ඇතිවන ශ්වසන රෝග සහ දර සෙවීමට වැයවන අධික කාලය", "වනාන්තර වැඩි වීම", "වැසි වැඩි වීම", "ගෙදර වාතය පිරිසිදු වීම",
        "පිරිසිදු ඉවුම්-පිහුම් ලිප් (Clean Cookstoves) හා LPG/විදුලි/ජීව වායු හඳුන්වා දීම SDG 7 හි වැදගත් කොටසකි."),
      q(t, "'පසෙහි කාබනික ද්‍රව්‍ය' (Soil Organic Matter / Humus) පවත්වා ගැනීම සම්පත් සංරක්ෂණයේදී තීරණාත්මක වන්නේ ඇයි?",
        "එය පසේ ජලය රඳවා ගැනීමේ ධාරිතාව වැඩි කරයි, පාංශු ජීවීන් පෝෂණය කරයි, පස බුරුල් කරයි සහ කාබන් ගබඩා කර ඛාදනය වළක්වයි", "පස තද ගල් බවට පත් කරයි", "පස ලවණ කරයි", "බෝග විනාශ කරයි",
        "කොම්පෝස්ට්, කොළ පොහොර (Green Manure) හා අවම බිම් සැකසීම (No-till Farming) මගින් පසෙහි හියුමස් මට්ටම ආරක්ෂා කෙරේ."),
      q(t, "'ජලයේ යූට්‍රොෆිකේෂන් / සුපෝෂණය' (Eutrophication) යන ජල සම්පත් දූෂණ ක්‍රියාවලිය සිදුවන්නේ කුමන හේතුව නිසාද?",
        "ගොවි බිම්වලින් හා අපජලයෙන් නයිට්‍රේට් හා පොස්පේට් පොහොර වැව්/ගංගාවලට ගලා යාමෙන් ඇල්ගී අධික ලෙස වැඩී (Algal Bloom) ජලයේ දියවූ ඔක්සිජන් අවසන් වී මසුන් මියයාම", "ජලය හිම බවට පත්වීම", "ජලය ඉතා පිරිසිදු වීම", "සූර්යාලෝකය නැති වීම පමණි",
        "වැව්වල ජපන් ජබර හා සැල්වීනියා අධිකව වැඩීමද බොහෝ විට පෝෂක දූෂණයේ ප්‍රතිඵලයකි."),
      q(t, "'බහු-කාර්ය කෘෂි වන වගාව' (Agroforestry) ගොවීන්ට සහ පරිසරයට එකවර වාසි ගෙන දෙන්නේ කෙසේද?",
        "එකම ගොවි බිමක ආහාර බෝග හෝ පශු පාලනය සමඟ දැව, පලතුරු හා නයිට්‍රජන් ස්ථාපිත කරන ගස් (උදා: ග්ලිරිසීඩියා, කොස්, ගම්මිරිස් ආධාරක) වැවීමෙන් ආදායම හා පාංශු ආරක්ෂාව වැඩිවීම", "සියලු ගස් ඉවත් කිරීම", "එක් බෝගයක් පමණක් වැවීම", "පස ගිනි තැබීම",
        "ශ්‍රී ලංකාවේ 'උඩරට ගෙවතු වගාව' (Kandyan Forest Gardens) ලොව ඉපැරණිතම හා සාර්ථකම කෘෂි වන වගා පද්ධතියකි."),
      q(t, "'ශ්‍රී ලංකාවේ කුඩා ජල විදුලි බලාගාර' (Mini Hydro Power Plants) වැඩි වශයෙන් ඉදිකර ඇත්තේ රටේ කුමන ප්‍රදේශවලද?",
        "රත්නපුර, කෑගල්ල, නුවරඑළිය, බදුල්ල හා මාතලේ වැනි මධ්‍යම කඳුකර හා සබරගමු බෑවුම්වල පිහිටි වේගවත් කුඩා දිය පහරවල් ආශ්‍රිතව", "මන්නාරම හා යාපනයේ", "පුත්තලම වැලි තලාවේ", "හම්බන්තොට ලේවායේ",
        "නිසි පාරිසරික අධ්‍යයනයකින් (EIA) තොරව කුඩා ජල විදුලි ව්‍යාපෘති ඉදි කිරීමෙන් දිය ඇලි හා මිරිදිය මසුන්ගේ වාසභූමිවලට බලපෑම් ඇතිවිය හැකිය."),
      q(t, "'සමුද්‍රීය ආරක්ෂිත කලාප' (Marine Protected Areas - MPAs) පිහිටුවීම මත්ස්‍ය සම්පතට උපකාරී වන්නේ කෙසේද?",
        "මසුන් අල්ලා ගැනීම තහනම් කළ අභිජනන කලාප ඇති කිරීමෙන් මත්ස්‍ය ගහනය යළි වර්ධනය වී අවට ධීවර කලාපවලටද මසුන් පැතිර යාම (Spillover Effect)", "සියලු ධීවරයන් සදාකාලිකව තහනම් කිරීම", "මුහුද වියළීම", "තෙල් ළිං ඉදිකිරීම",
        "ශ්‍රී ලංකාවේ පරෙවි දූපත (Pigeon Island), හික්කඩුව හා බාර් රීෆ් මෙවැනි සාගර උද්‍යාන වේ."),
      q(t, "'විදුලි පරිභෝජන උච්ච ඉල්ලුම' (Peak Electricity Demand) කළමනාකරණය කිරීමට 'වේලාව අනුව ගාස්තු ක්‍රමය' (Time-of-Use Tariff) උපකාරී වන්නේ කෙසේද?",
        "සවස 6:30–10:30 වැනි උච්ච වේලාවන්හි විදුලි ගාස්තුව වැඩි කර රාත්‍රී/දහවල් අඩු ඉල්ලුම් වේලාවන්හි ගාස්තුව අඩු කිරීමෙන් කර්මාන්ත හා පාරිභෝගිකයන් භාවිතය වෙනස් වේලාවකට මාරු කිරීමට පෙළඹවීම", "සියලු විදුලිය දවස පුරා විසන්ධි කිරීම", "මීටර් ගලවා දැමීම", "බල්බ විකිණීම තහනම් කිරීම",
        "මෙමගින් මිල අධික හදිසි ඩීසල් බලාගාර ක්‍රියාත්මක කිරීමේ අවශ්‍යතාව අඩු වේ."),
      q(t, "'ස්වාභාවික වනාන්තර' හා 'වාණිජ වන වගා' (Forest Plantations - උදා: පයිනස්, යුකැලිප්ටස්, තේක්ක) අතර පාරිසරික වෙනස කුමක්ද?",
        "ස්වාභාවික වනාන්තරවල ඉහළ ජෛව විවිධත්වයක් හා ස්ථර කිහිපයක ශාක පද්ධතියක් පවතින අතර ඒක-බෝග වාණිජ වන වගාවල ජෛව විවිධත්වය ඉතා අඩු වන අතර පස හා ජල උරාගැනීමටද බලපෑම් ඇති කළ හැකිය", "වාණිජ වන වගාවල ජෛව විවිධත්වය 10 ගුණයකින් වැඩිය", "දෙකේම වෙනසක් නැත", "පයිනස් වගාවල සිංහරාජයට වඩා ආවේණික සතුන් සිටී",
        "මධ්‍යම කඳුකරයේ පැරණි පයිනස් වගා ක්‍රමයෙන් දේශීය ශාක සහිත ස්වාභාවික වනාන්තර බවට පරිවර්තනය කිරීමේ ව්‍යාපෘති ක්‍රියාත්මක කෙරේ."),
      q(t, "'බලශක්ති මිශ්‍රණය' (Energy Mix) විවිධාංගීකරණය කිරීම රටක ජාතික ආරක්ෂාවට වැදගත් වන්නේ ඇයි?",
        "තනි බලශක්ති ප්‍රභවයක් (උදා: ආනයනික තෙල් හෝ නියඟයකදී ජල විදුලිය) මත පමණක් රඳා නොසිට සූර්ය, සුළං, ජල, ජෛව හා ගබඩා පද්ධති සමබරව භාවිත කිරීමෙන් බලශක්ති අර්බුද වළක්වා ගත හැකි බැවින්", "එක් බලාගාරයක් පමණක් තබා ගැනීමට", "විදුලි බිල වැඩි කිරීමට", "සූර්ය බලය ඉවත් කිරීමට",
        "ලෝක වෙළඳපොළේ තෙල් මිල ඉහළ යන අවස්ථාවලදී විවිධාංගීකරණය වූ බලශක්ති පද්ධතියක් රට ආරක්ෂා කරයි."),
      q(t, "'ප්‍රකාශ වෝල්ටීයතා' (Solar PV) පැනල නිෂ්පාදනයේදී මූලික අර්ධ සන්නායක ද්‍රව්‍යය ලෙස භාවිත කරන්නේ කුමන ඛනිජයෙන් නිස්සාරණය කරන මූලද්‍රව්‍යයක්ද?",
        "සිලිකන් (Silicon - ක්වාර්ට්ස්/සිලිකා වැලිවලින් ලබා ගනී)", "යකඩ", "රසදිය", "ඊයම්",
        "පසුගිය දශකය තුළ සූර්ය පැනල නිෂ්පාදන පිරිවැය 85% කට වඩා පහත වැටීම නිසා එය ලොව ලාභදායීම විදුලි ප්‍රභවයක් බවට පත්ව ඇත."),
      q(t, "'ශ්‍රී ලංකාවේ වියළි කලාපයේ මිරිදිය ධීවර කර්මාන්තය' (Inland Fisheries) ප්‍රධාන වශයෙන් රඳා පවතින්නේ කුමන සම්පත මතද?",
        "පරාක්‍රම සමුද්‍රය, මින්නේරිය, සේනානායක සමුද්‍රය, උඩවලව හා වික්ටෝරියා වැනි පුරාණ හා නවීන මහා වැව් හා ජලාශ", "සාගරයේ ගැඹුරු කොරල්පර", "හිම දියවන ගංගා", "කලපු පමණි",
        "තිලාපියා, රෝහු, කැට්ලා හා මිරිදිය ඉස්සන් වගාව වියළි කලාපීය ජනතාවට අඩු මිලට ප්‍රෝටීන් සපයන වැදගත් ආර්ථික මාර්ගයකි."),
      q(t, "'ඛනිජ සම්පත් සඳහා නැවත පණ දීම / නාගරික පතල් කැණීම' (Urban Mining) යනු කුමක්ද?",
        "ඉවතලන ජංගම දුරකථන, පරිගණක හා ඉලෙක්ට්‍රොනික අපද්‍රව්‍ය (E-waste) වලින් රන්, රිදී, තඹ, පැලේඩියම් හා දුර්ලභ ලෝහ නිස්සාරණය කර නැවත භාවිත කිරීම", "නගර මැද ගැඹුරු ගල් වළවල් හෑරීම", "පාසල් පිට්ටනිවල තෙල් සෙවීම", "ගල් අඟුරු පිළිස්සීම",
        "ටොන් එකක ඉවතලන ස්මාර්ට්ෆෝන් පරිපථ පුවරුවල රත්‍රන් සාන්ද්‍රණය ස්වාභාවික රන් ආකර ලෝපස් ටොන් එකකට වඩා බොහෝ සෙයින් වැඩිය."),
      q(t, "'සංචාරක සම්පතක් ලෙස සාගරය හා වෙරළ' ආරක්ෂා කිරීමේදී 'නිල් ධජ සහතිකය' (Blue Flag Certification) ලබා දෙන්නේ කුමන කරුණු සපුරන වෙරළ තීරවලටද?",
        "ඉහළ ජල පිරිසිදුකම, පරිසර කළමනාකරණය, ආරක්ෂාව (ජීවිතාරක්ෂක සේවා) සහ පරිසර අධ්‍යාපන ප්‍රමිතීන්", "වැඩිම කුණු ගොඩවල් ඇති වෙරළට", "නිල් පැහැති ගොඩනැගිලි ඇති නගරවලට", "තෙල් කාන්දු වන වරායවලට",
        "කසළ, ප්ලාස්ටික් හා අපජලය වෙරළට බැහැර කිරීම වැළැක්වීම වෙරළබඩ සංචාරක ආර්ථිකයට අත්‍යවශ්‍ය වේ."),
      q(t, "'ජල පරිභෝජනයේ කර්මාන්ත අංශයේ' පරිසර දූෂණය වැළැක්වීම සඳහා 'ශුන්‍ය ද්‍රව විසර්ජන' (Zero Liquid Discharge - ZLD) පද්ධති භාවිත කරන්නේ කුමක් සඳහාද?",
        "රෙදිපිළි සායම් කිරීම, සම් පදම් කිරීම හා රසායනික කර්මාන්තශාලාවලින් පිටවන අපජලය සම්පූර්ණයෙන් පිරිපහදු කර කර්මාන්තශාලාව තුළම නැවත භාවිත කිරීම (ගංගාවලට මුදා නොහැර)", "සියලු අපජලය කෙලින්ම ළිංවලට දැමීමට", "ජලය නොමැතිව කම්හල වැසීමට", "මුහුදට පොම්ප කිරීමට",
        "ශ්‍රී ලංකාවේ බියගම හා කටුනායක වැනි අපනයන සැකසුම් කලාපවල මධ්‍යගත අපජල පිරිපහදු පද්ධති (CETPs) ක්‍රියාත්මක වේ."),
      q(t, "ස්වාභාවික සම්පත් කළමනාකරණයේදී 'පාරිසරික බලපෑම් තක්සේරුව' (Environmental Impact Assessment - EIA) අනිවාර්ය කර ඇත්තේ ඇයි?",
        "මහාමාර්ග, වේලි, බලාගාර හෝ පතල් වැනි මහා පරිමාණ ව්‍යාපෘතියක් ආරම්භ කිරීමට පෙර ඉන් පරිසරයට හා ජනතාවට වන හානිය පුරෝකථනය කර අවම කිරීමේ ක්‍රම සැලසුම් කිරීමට", "ව්‍යාපෘති සම්පූර්ණයෙන් නතර කිරීමට පමණි", "වනාන්තර කැපීමට අවසර දීමට", "මුදල් නාස්ති කිරීමට",
        "මහජන අදහස් විමසීමද ශ්‍රී ලංකාවේ ජාතික පාරිසරික පනත යටතේ EIA ක්‍රියාවලියේ වැදගත් කොටසකි."),
      q(t, "'ඛනිජ තෙල් සඳහා විකල්ප ප්‍රවාහන බලශක්ති' අතර දුම්රිය ජාල විද්‍යුත්කරණය (Railway Electrification) ඉතා ඵලදායී වන්නේ ඇයි?",
        "විදුලි දුම්රිය ඩීසල් දුම්රියට වඩා බලශක්ති කාර්යක්ෂම වන අතර, පුනර්ජනනීය විදුලිය භාවිතයෙන් ප්‍රවාහන කාබන් විමෝචනය හා ආනයනික ඩීසල් වියදම විශාල ලෙස අඩු කරන බැවින්", "විදුලි දුම්රිය ධාවනයට ගල් අඟුරු වැඩියෙන් වැය වන නිසා", "රේල් පීලි අවශ්‍ය නොවන නිසා", "මගීන් ගණන අඩු කරන නිසා",
        "යුරෝපය, ජපානය, චීනය හා ඉන්දියාව සිය දුම්රිය ජාලයන්ගෙන් බහුතරය විද්‍යුත්කරණය කර ඇත."),
      q(t, "'ජල උල්පත් සහ දිය ඇලි' සංරක්ෂණය කිරීමේදී ඉහළ බෑවුම්වල 'රොටරි ගොවිතැන හෝ ඝන අත්තිවාරම් ඉදිකිරීම්' සීමා කරන්නේ ඇයි?",
        "මුල් පස ගැලවී යාමෙන් වැසි ජලය පොළොවට උරා නොගෙන ක්ෂණිකව ගලා යන බැවින් වියළි කාලයේදී උල්පත් සිඳී ගොස් වැසි කාලයේ නායයෑම් ඇති වන නිසා", "දිය ඇලි ඉහළට ගලන නිසා", "ගස් ජලය බොන නිසා", "වැස්ස වැඩිවන නිසා",
        "කඳුකර ජල පෝෂකවල උණ ගස් හා දේශීය ගස් වර්ග සිටුවීම උල්පත් සුරැකීමට ඉතා සුදුසුය."),
      q(t, "'ග්ලැසියර දියවීම' (Glacier Retreat) ආසියාවේ හා දකුණු ඇමරිකාවේ මිලියන සිය ගණනක් ජනතාවගේ ජල සම්පතට තර්ජනයක් වන්නේ කෙසේද?",
        "හිමාලය හා ඇන්ඩීස් ග්ලැසියර ගිම්හාන කාලයේදී ගංගාවලට (ගංගා, ඉන්දු, යැංසි, මීකොං) අඛණ්ඩ ජලය සපයන 'ජල කුළුණු' ලෙස ක්‍රියා කරන බැවින් ඒවා දියවී අවසන් වූ පසු දැඩි වාරි හා පානීය ජල හිඟයක් ඇතිවේ", "ග්ලැසියරවල ඇත්තේ ලුණු ජලය බැවින්", "ගංගා මුහුදෙන් ආරම්භ වන බැවින්", "හිම කිසිදා දිය නොවන බැවින්",
        "හිමාලය 'තෙවන ධ්‍රැවය' (Third Pole) ලෙස හඳුන්වනු ලබන්නේ ධ්‍රැව කලාපවලින් පිටත විශාලතම අයිස් සංචිතය එහි පවතින බැවිනි."),
      q(t, "'සූර්ය උණුසුම් ජල පද්ධති' (Solar Water Heaters) ගොඩනැගිලිවල සවි කිරීම බලශක්ති ඉතිරියට දායක වන්නේ කෙසේද?",
        "විදුලි හෝ ගෑස් හීටර් භාවිත නොකර සෘජුවම සූර්ය තාපයෙන් ජලය රත් කර ගැනීමෙන් ගෘහස්ථ හා හෝටල් විදුලි පරිභෝජනය සැලකිය යුතු ලෙස අඩු කිරීම", "ජලය සීතල කිරීම", "විදුලි පරිභෝජනය වැඩි කිරීම", "සූර්ය රශ්මිය අවහිර කිරීම",
        "නිවර්තන රටවල හෝටල්, රෝහල් හා නිවාස සඳහා මෙය ඉතා ලාභදායී හා සරල පුනර්ජනනීය තාක්ෂණයකි."),
      q(t, "'නීති විරෝධී වැලි ගොඩදැමීම' (Illegal Sand Mining) ගංගා පරිසර පද්ධතිවලට හා සම්පත්වලට බරපතල හානි කරන්නේ කෙසේද?",
        "ගං පතුල ගැඹුරු වීම නිසා පාලම් කණු හෑරී කඩා වැටීම, ගං ඉවුරු කඩා යාම, අවට ළිංවල ජල මට්ටම පහත වැටීම සහ ගංගා මෝයට මුහුදු ලවණ ජලය ඇතුළු වීම", "ගංගාවේ ජලය වැඩි වීම", "වෙරළ පුළුල් වීම", "මසුන් වැඩි වීම",
        "ඉදිකිරීම් සඳහා ගංගා වැලි වෙනුවට ගල් කුඩු (Manufactured Sand / M-Sand) හා මුහුදු වැලි පිරිසැකසුම් කර භාවිත කිරීම විකල්ප විසඳුමකි."),
      q(t, "'බලශක්ති ශ්‍රේණිගත කිරීමේ ලේබල' (Energy Efficiency Star Labels - ශීතකරණ, වායු සමීකරණ මත තරු 5 සලකුණ) පාරිභෝගිකයන්ට උපකාරී වන්නේ කෙසේද?",
        "වැඩිම බලශක්ති කාර්යක්ෂමතාවයකින් යුත් අඩුම විදුලියක් වැය කරන උපකරණ හඳුනාගෙන මිලදී ගැනීමට මග පෙන්වීම", "උපකරණයේ බර පෙන්වීම", "උපකරණයේ වර්ණය පෙන්වීම", "වැඩි විදුලියක් වැය වන බව පැවසීම",
        "තරු 5 (5-Star) ඉන්වර්ටර් උපකරණ භාවිතය මගින් මාසික විදුලි බිල හා ජාතික බලශක්ති ඉල්ලුම අඩු කර ගත හැකිය."),
      q(t, "'විශ්වීය ජල උරුමය / පානීය ජල අයිතිය' යටතේ එක්සත් ජාතීන්ගේ සංවිධානය පිළිගෙන ඇති මූලික ප්‍රතිපත්තිය කුමක්ද?",
        "පිරිසිදු, ආරක්ෂිත පානීය ජලය හා සනීපාරක්ෂාව සෑම මිනිසෙකුගේම මූලික මානව අයිතිවාසිකමක් වීම", "ජලය ධනවතුන්ට පමණක් අයිති වීම", "මුහුදු ජලය පමණක් මානව අයිතියක් වීම", "ජලය ව්‍යාපාරික ලාභය සඳහා පමණක් වීම",
        "ලොව පුරා බිලියන 2 කට ආසන්න ජනතාවකට තවමත් නිවස තුළ ආරක්ෂිතව කළමනාකරණය කළ පානීය ජල සැපයුමක් නොමැත."),
      q(t, "'ජෛව ඛනිජ හා පරිසර හිතකාමී ගොඩනැගිලි ද්‍රව්‍ය' (Green Building Materials) ලෙස ඉදිකිරීම් සම්පත්වල නව ප්‍රවණතාව කුමක්ද?",
        "ඉහළ කාබන් විමෝචනයක් ඇති සිමෙන්ති හා පිළිස්සූ ගඩොල් ප්‍රමාණය අඩු කර පීඩිත මැටි බ්ලොක් (CSEB), ප්‍රතිචක්‍රීකරණය කළ වානේ, උණ බම්බු හා සහතික කළ දැව භාවිතය", "සම්පූර්ණ වීදුරු ගොඩනැගිලි නිවර්තන රටවල ඉදිකිරීම", "ඇස්බැස්ටස් භාවිතය වැඩි කිරීම", "ගංගා වැලි පමණක් භාවිතය",
        "ස්වාභාවික වාතාශ්‍රය හා දිවා ආලෝකය උපරිම ලෙස යොදා ගැනීමෙන් ගොඩනැගිලිවල විදුලි පරිභෝජනයද අඩු වේ."),
      q(t, "ලෝකයේ 'පොසිල ඉන්ධන මිල හා සැපයුමට' බලපාන විශාලතම භූගෝලීය 'නාවික ගෙල පටු ස්ථාන' (Maritime Chokepoints) දෙක මොනවාද?",
        "හෝමූස් සමුද්‍ර සන්ධිය (Strait of Hormuz - පර්සියානු ගල්ෆ්) සහ මලක්කා සමුද්‍ර සන්ධිය (Strait of Malacca)", "බේරිං සමුද්‍ර සන්ධිය හා මැගලන් සමුද්‍ර සන්ධිය", "කුක් සමුද්‍ර සන්ධිය හා බාස් සමුද්‍ර සන්ධිය", "පෝක් සමුද්‍ර සන්ධිය හා ඩේවිස් සමුද්‍ර සන්ධිය",
        "ලෝක මුහුදු මගින් ප්‍රවාහනය කරන ඛනිජ තෙල්වලින් ~20%–30% ක් හෝමූස් සමුද්‍ර සන්ධිය හරහා ගමන් කරයි."),
      q(t, "'නියඟයට ඔරොත්තු දෙන ජල කළමනාකරණය' සඳහා පුරාණ ශ්‍රී ලංකාවේ වැව්වල පැවති 'බිසෝකොටුව' සහ 'කට්ටකාඩුව' වැනි අංග ඉටු කළ කාර්යය කුමක්ද?",
        "බිසෝකොටුව ජල පීඩනය පාලනය කරමින් සොරොව්ව ආරක්ෂිතව විවෘත කිරීමටත්, කට්ටකාඩුව වැව් බැම්මට කාන්දු වන ජලයේ ලවණ හා අපද්‍රව්‍ය පෙරා බැම්ම ශක්තිමත් කිරීමටත් උපකාරී විය", "මසුන් ඇල්ලීම පමණි", "බෝට්ටු පැදීම පමණි", "වැව සිඳී යාමට සැලැස්වීම",
        "පුරාණ ශ්‍රී ලාංකික වාරි ඉංජිනේරු තාක්ෂණය ස්වාභාවික සම්පත් තිරසාරව භාවිත කිරීමේ ලෝක පූජිත නිදසුනකි."),
      q(t, "'අන්තර්-රාජ්‍ය පුනර්ජනනීය බලශක්ති හුවමාරුව' (Cross-border Renewable Power Grids) අනාගත බලශක්ති සම්පත් කළමනාකරණයට වැදගත් වන්නේ ඇයි?",
        "එක් රටක අතිරික්ත සූර්ය/සුළං/ජල විදුලිය අධි-වෝල්ටීයතා රැහැන් (HVDC) මගින් විදුලි ඉල්ලුම වැඩි අසල්වැසි රටකට හුවමාරු කර බලශක්ති සුරක්ෂිතතාව වැඩි කිරීමට", "රැහැන් කපා දැමීමට", "විදුලිය නාස්ති කිරීමට", "ගල් අඟුරු වැඩි කිරීමට",
        "උදාහරණයක් ලෙස නෝර්වේ රට ජල විදුලිය ජර්මනිය හා බ්‍රිතාන්‍යය සමඟ මුහුදු යට කේබල් මගින් හුවමාරු කරයි."),
      q(t, "'ඛනිජ හා බලශක්ති සම්පත්' අතර 'මයිකා / අභ්‍රක' (Mica) ඛනිජය විදුලි හා ඉලෙක්ට්‍රොනික කර්මාන්තයේදී ඉතා ප්‍රයෝජනවත් වන්නේ කුමන භෞතික ගුණාංගය නිසාද?",
        "ඉහළ තාප ප්‍රතිරෝධය හා විශිෂ්ට විද්‍යුත් පරිවාරක (Electrical Insulator) ගුණාංගය", "ඉහළ විද්‍යුත් සන්නායකතාව", "ජලයේ ඉක්මනින් දියවීම", "චුම්භක ආකර්ෂණය",
        "ශ්‍රී ලංකාවේ මාතලේ, නාවලපිටිය හා බදුල්ල ප්‍රදේශවලද ෆ්ලෝගෝපයිට් හා මස්කොවයිට් මයිකා නිධි හමුවේ."),
      q(t, "'ෆෙල්ඩ්ස්පාර්' (Feldspar) ඛනිජය ශ්‍රී ලංකාවේ කැණීම් කරනු ලබන අතර එය ප්‍රධාන වශයෙන් යොදා ගන්නේ කුමන නිෂ්පාදන සඳහාද?",
        "සෙරමික් පිඟන් භාණ්ඩ, පෝසිලේන්, නාන කාමර උපකරණ හා වීදුරු නිෂ්පාදනයේදී ගලා යාම පහසු කරන Flux ද්‍රව්‍යයක් ලෙස", "රබර් ටයර් සෑදීමට", "තේ ඇසුරුම් කිරීමට", "ලුණු පිරිපහදුවට",
        "රත්තොට, ඕවිලිකන්ද හා කොස්ලන්ද ප්‍රදේශවල ෆෙල්ඩ්ස්පාර් නිධි ව්‍යාප්තව ඇත."),
      q(t, "'පුනර්ජනනීය බලශක්ති ආයෝජනවලදී' රටක 'සූර්ය වහල මත විදුලි ජනන' (Rooftop Solar - Net Metering / Net Accounting) ක්‍රමය ජනප්‍රිය වී ඇත්තේ ඇයි?",
        "නිවාස හා කර්මාන්තශාලා තමන්ට අවශ්‍ය විදුලිය නිපදවා ගන්නා අතර අතිරික්ත විදුලිය ජාතික පද්ධතියට අලෙවි කර ආදායමක් ලැබිය හැකි බැවින්", "වහල කඩා වැටෙන බැවින්", "රාත්‍රියේ වැඩිපුර විදුලිය දෙන බැවින්", "විදුලි බිල දෙගුණ වන බැවින්",
        "එසේම විදුලිය නිපදවන ස්ථානයේම භාවිත වන නිසා රැහැන් පද්ධතිවල සම්ප්‍රේෂණ හානිය (Transmission Loss) අවම වේ."),
      q(t, "'ජල පරිභෝජන කළමනාකරණයේදී' 'බිංදු ජල සම්පාදනය' (Drip Irrigation) සම්ප්‍රදායික ඇළ මගින් ගොවි බිම් ගංවතුර පිරවීමට (Flood Irrigation) වඩා කාර්යක්ෂම වන්නේ ඇයි?",
        "නළ මගින් ජලය කෙලින්ම ශාකයේ මුල් කලාපයට බිංදු වශයෙන් සපයන බැවින් වාෂ්පීභවනය හා අපතේ යාම 50%–70% කින් අඩු වේ", "වල් පැළෑටි වැඩීම වැඩි කරයි", "ජලය දස ගුණයකින් වැඩිපුර වැය වේ", "පස සම්පූර්ණයෙන් සෝදා හරී",
        "ඊශ්‍රායලය හා ශ්‍රී ලංකාවේ කල්පිටිය/මහඉලුප්පල්ලම වියළි කලාපීය වගාවන්හි මෙය සාර්ථකව භාවිත කෙරේ."),
      q(t, "'බොරතෙල් පිරිපහදු කිරීමේදී' (Petroleum Refining - උදා: සපුගස්කන්ද තෙල් පිරිපහදුව) භාගික ආසවනය මගින් ලැබෙන විවිධ අතුරු නිෂ්පාදන මොනවාද?",
        "LPG ගෑස්, පෙට්‍රල්, භූමිතෙල්, ගුවන් යානා ඉන්ධන, ඩීසල්, දැවිතෙල් සහ මාර්ග තාර (Bitumen)", "යපස් සහ ඇලුමිනියම්", "සීනි සහ තේ", "කඩදාසි සහ රෙදි",
        "ප්ලාස්ටික්, කෘත්‍රිම පොහොර හා පොලියෙස්ටර් රෙදි සඳහාද පෙට්‍රෝ-රසායනික අමුද්‍රව්‍ය මින් ලැබේ."),
      q(t, "'සාගර තෙල් හා ස්වාභාවික වායු කැණීම් වේදිකා' (Offshore Drilling Rigs - උදා: උතුරු මුහුද, මෙක්සිකෝ බොක්ක) පිහිටා ඇත්තේ සාගරයේ කුමන කලාපයේද?",
        "නොගැඹුරු මහාද්වීපික තටාකයේ (Continental Shelf) හා මහාද්වීපික බෑවුමේ", "සාගර අගාධ පතුලේ (මීටර් 10,000)", "කොරල් දූපත් මත", "ගංගා ඇළවල්වල",
        "මහාද්වීපික තටාකවල වසර මිලියන ගණනක් පුරා රැස් වූ සාගර කාබනික අවසාදිත හයිඩ්‍රොකාබන නිධි බවට පත්ව ඇත."),
      q(t, "'ස්වාභාවික වනාන්තරවල ශීඝ්‍ර විනාශය' (Deforestation) නිසා ඇමසන්, කොංගෝ හා බෝර්නියෝ වැනි කලාපවලට සිදුවන ප්‍රධාන පාරිසරික බලපෑම් මොනවාද?",
        "ජෛව විවිධත්වය වඳ වී යාම, ගබඩා වූ කාබන් වායුගෝලයට මුදා හැරීම, පාංශු ඛාදනය සහ කලාපීය වර්ෂාපතන රටා වෙනස් වීම", "වන සතුන් වැඩි වීම", "ඔක්සිජන් ප්‍රමාණය දෙගුණ වීම", "පස වඩාත් සාරවත් වීම",
        "ඇමසන් වනාන්තරය 'පියාඹන ගංගා' (Flying Rivers) ලෙස දකුණු ඇමරිකාව පුරා වැසි සැපයීමටද උපකාරී වේ."),
      q(t, "'සම්පත් සංරක්ෂණයේ 5R සංකල්පය' (Refuse, Reduce, Reuse, Repurpose, Recycle) පිළිබඳ නිවැරදි ප්‍රමුඛතා අනුපිළිවෙල කුමක්ද?",
        "ප්‍රතික්ෂේප කිරීම (Refuse - අනවශ්‍ය ප්ලාස්ටික්) හා පරිභෝජනය අඩු කිරීම (Reduce) ප්‍රථමයෙන්ද, නැවත භාවිතය (Reuse) ඉන්පසුවද, ප්‍රතිචක්‍රීකරණය (Recycle) අවසාන පියවර ලෙසද ක්‍රියාත්මක කිරීම", "පළමුව විසි කර පසුව පිළිස්සීම", "සියල්ල මුහුදට දැමීම", "Recycle කිරීමෙන් පසු භාවිතය වැඩි කිරීම",
        "මූලිකවම අපද්‍රව්‍ය ජනනය නොවී වළක්වා ගැනීම (Prevention) ප්‍රතිචක්‍රීකරණයටත් වඩා බලශක්ති ඉතිරියක් ලබා දෙයි."),
      q(t, "'ජලයේ බැර ලෝහ දූෂණය' (Heavy Metal Pollution - රසදිය, ඊයම්, කැඩ්මියම්, ආසනික්) ජලජ පරිසර පද්ධතිවලදී අතිශයින් භයානක වන්නේ ඇයි?",
        "ඒවා ජීව විද්‍යාත්මකව දිරාපත් නොවන අතර ආහාර දාමයේ ඉහළට යත්ම මසුන් හා මිනිසුන් තුළ සාන්ද්‍රණය ඉහළ යන ('ජෛව විශාලනය' / Biomagnification) බැවින්", "ඒවා පැයකින් වාෂ්ප වන බැවින්", "ඒවා විටමින් බවට පත්වන බැවින්", "ඒවා මසුන්ට ශක්තිය දෙන බැවින්",
        "ජපානයේ මිනමාටා (Minamata) රෝගය රසදිය දූෂණයෙන් ඇතිවූ ප්‍රකට ඛේදවාචකයකි."),
      q(t, "'කෘත්‍රිම මෝසම් හෝ වලාකුළු බීජකරණය' (Cloud Seeding) ඇතැම් ජල හිඟ රටවල් භාවිත කරන්නේ කුමන අරමුණක් සඳහාද?",
        "වායුගෝලයේ ඇති තෙතමනය සහිත වලාකුළු තුළට සිල්වර් අයඩයිඩ් (Silver Iodide) වැනි අංශු ඉස වර්ෂාපතනය ඇති කිරීම උත්තේජනය කිරීමට", "හිරු නිවා දැමීමට", "සාගර ජලය හිස් කිරීමට", "සුළි කුණාටු සෑදීමට",
        "කෙසේ වෙතත් මෙම ක්‍රමය දැනටමත් වලාකුළු පවතින විට පමණක් සීමිතව ක්‍රියාත්මක වන අතර ස්ථිර නියං විසඳුමක් නොවේ."),
      q(t, "'තාප විදුලි බලාගාර' (Thermal Power Plants) බොහෝ විට විශාල ගංගා හෝ මුහුදු වෙරළ ආසන්නයේ ඉදි කිරීමට ප්‍රධාන තාක්ෂණික හේතුව කුමක්ද?",
        "ටර්බයින කරකැවීමෙන් පසු ඉහළ උෂ්ණත්ව වාෂ්ප සිසිල් කර නැවත ජලය බවට පත් කිරීම සඳහා විශාල සිසිලන ජල සැපයුමක් අවශ්‍ය බැවින්", "සේවකයන්ට පිහිනීමට", "මසුන් ඇල්ලීමට", "වාෂ්ප අහසට යැවීමට",
        "එබැවින් තාප බලාගාරවලින් පිටවන උණුසුම් ජලය 'තාප දූෂණය' (Thermal Pollution) ඇති නොවන පරිදි සිසිල් කුළුණු මගින් පාලනය කළ යුතුය."),
      q(t, "'ජල සුරක්ෂිතතාව' (Water Security) යනු කුමක්ද?",
        "පරිසර පද්ධති සුරකිමින් පානයට, සනීපාරක්ෂාවට, කෘෂිකර්මයට හා ආර්ථිකයට ප්‍රමාණවත් සහ පිරිසිදු ජලය තිරසාරව හා සාධාරණව ලබාගත හැකි වීමත් ජල ආශ්‍රිත ආපදාවලින් ආරක්ෂිත වීමත්", "ජලය ටැංකිවල සඟවා තැබීම", "වැසි ජලය මුහුදට යැවීම", "ජල මිල අසීමිතව වැඩි කිරීම",
        "නියඟය, ගංවතුර හා ජල දූෂණය යන තුනම ජල සුරක්ෂිතතාවයට තර්ජන එල්ල කරයි."),
      q(t, "'ස්වාභාවික සම්පත් වටිනාකම් හා දරාගැනීමේ ධාරිතාව' අනුව 'වන සංරක්ෂණය සඳහා ජාතික වන රක්ෂිත හා වනජීවී දෙපාර්තමේන්තු' පිහිටුවා ඇත්තේ ඇයි?",
        "නීතිවිරෝධී දඩයම, දැව හෙළීම, වන අලි/වන සතුන් අනවසර වෙළඳාම හා වනාන්තර ඉඩම් අත්පත් කර ගැනීම වැළැක්වීම සඳහා", "වනාන්තර විකිණීම සඳහා", "සතුන් ඉවත් කිරීම සඳහා", "ගල් පතල් පිහිටුවීම සඳහා",
        "ශ්‍රී ලංකාවේ වන සංරක්ෂණ දෙපාර්තමේන්තුව හා වනජීවී සංරක්ෂණ දෙපාර්තමේන්තුව රටේ භූමියෙන් 28% කට ආසන්න ආරක්ෂිත කලාප කළමනාකරණය කරයි."),
      q(t, "'ස්වාභාවික වායු තැන්පතු' (Natural Gas Deposits) ශ්‍රී ලංකාව ආශ්‍රිතව ගවේෂණය කර සොයාගෙන ඇත්තේ කුමන සාගර ද්‍රෝණියේද?",
        "මන්නාරම් ද්‍රෝණිය (Mannar Basin)", "ත්‍රිකුණාමලය කඳු මුදුන", "විල්පත්තු වනය", "හෝර්ටන් තැන්න",
        "මන්නාරම් ද්‍රෝණියේ සිදු කළ භූ කම්පන සමීක්ෂණ හා ගවේෂණ කැණීම්වලින් ස්වාභාවික වායු විභවය හඳුනාගෙන ඇත."),
      q(t, "'විදුලි බැටරි ප්‍රතිචක්‍රීකරණය' (Battery Recycling) හරිත බලශක්ති සංක්‍රාන්තියේදී වැදගත් වන්නේ ඇයි?",
        "භාවිත කළ ලිතියම්-අයන් බැටරිවලින් ලිතියම්, කොබෝල්ට්, නිකල් හා මැංගනීස් වැනි වටිනා ලෝහ නැවත ලබාගෙන අලුතින් පතල් කැණීමේ අවශ්‍යතාව හා ඊ-අපද්‍රව්‍ය විෂ වීම අඩු කිරීමට", "බැටරි ගිනි තැබීමට", "සාගරයට දැමීමට", "ගල් අඟුරු සෑදීමට",
        "බැටරි අපද්‍රව්‍ය සාමාන්‍ය කසළ සමඟ බැහැර කිරීමෙන් ගිනි ගැනීම් හා බැර ලෝහ කාන්දු වීම් සිදුවේ."),
      q(t, "'පුනර්ජනනීය ජෛව ඩීසල් හා තිරසාර ගුවන් යානා ඉන්ධන' (SAF - Sustainable Aviation Fuel) නිපදවීමට ඉවතලන පිසූ තෙල් (Used Cooking Oil) යොදා ගන්නේ ඇයි?",
        "අලුතින් වගා බිම් හෙළි නොකර අපද්‍රව්‍ය තෙල් ප්‍රයෝජනවත් ඉන්ධනයක් බවට පත් කර ගුවන් ගමන්වල කාබන් පියසටහන ~80% දක්වා අඩු කිරීමට", "ගුවන් යානා වේගය අඩු කිරීමට", "කසළ වැඩි කිරීමට", "ආහාර පිසීම තහනම් කිරීමට",
        "ගුවන් ප්‍රවාහනය සඳහා බැටරි භාවිතය අපහසු බැවින් SAF ප්‍රධාන විකල්පයකි."),
      q(t, "'කළුගල්, වැලි හා මැටි' වැනි ඉදිකිරීම් ඛනිජ සම්පත් ප්‍රවාහන පිරිවැය අධික සම්පත් ලෙස හඳුන්වන්නේ ඇයි?",
        "ඒවායේ බර ඉතා වැඩි නමුත් ඒකක වටිනාකම අඩු බැවින් දිගු දුර ප්‍රවාහනය කිරීමේදී ප්‍රවාහන ගාස්තුව ඛනිජයේ වටිනාකම ඉක්මවා යන නිසා", "ඒවා ඉතා සැහැල්ලු නිසා", "ඒවා රන් මෙන් මිල අධික නිසා", "ඒවා ගුවනින් ගෙන යන නිසා",
        "එබැවින් ඉදිකිරීම් කර්මාන්ත සඳහා මෙම ද්‍රව්‍ය හැකිතාක් ඉදිකිරීම් ස්ථානයට ආසන්න ප්‍රදේශවලින් සපයා ගැනේ."),
      q(t, "'ජල පෝෂක වනාන්තරවලට පිවිසෙන ප්ලාස්ටික් හා පොලිතීන්' සම්පත් කළමනාකරණයේදී ගැටලුවක් වන්නේ ඇයි?",
        "ඒවා සියවස් ගණනාවක් නොදිරා පසේ ජල උරාගැනීම අවහිර කරයි, කාණු හා ඇළ මාර්ග හිර කර ගංවතුර ඇති කරයි සහ ක්ෂුද්‍ර ප්ලාස්ටික් (Microplastics) ලෙස ජලයට එක්වේ", "ඒවා ඉක්මනින් පොහොර වේ", "ඒවා ජලය පිරිසිදු කරයි", "සතුන්ට පෝෂ්‍යදායී ආහාර වේ",
        "එක් වරක් භාවිත කරන පොලිතීන් තහනම් කිරීම හා නැවත පිරවිය හැකි බෝතල් භාවිතය මීට ප්‍රධාන පිළියමකි."),
      q(t, "'ඛනිජ තෙල් සංචිත ක්ෂය වීමත් සමඟ' මැදපෙරදිග සෞදි අරාබිය හා එක්සත් අරාබි එමීර් රාජ්‍යය වැනි රටවල් අනාගත ආර්ථිකය සඳහා ගන්නා උපායමාර්ගය කුමක්ද?",
        "තෙල් ආදායම ආයෝජනය කරමින් සූර්ය බලශක්ති, සංචාරක, ගුවන් සේවා, මූල්‍ය හා තාක්ෂණික ක්ෂේත්‍ර වෙත ආර්ථිකය විවිධාංගීකරණය කිරීම", "සියලු නගර වසා දැමීම", "ගල් අඟුරු සෙවීම පමණි", "සංචාරකයන් තහනම් කිරීම",
        "ඩුබායි නගරය මැදපෙරදිග ප්‍රධාන සංචාරක, වෙළඳ හා ගුවන් මධ්‍යස්ථානයක් බවට පත්වීම මීට නිදසුනකි."),
      q(t, "'විදුලි බල පද්ධතිවල බලශක්ති සංරක්ෂණය' සඳහා ගොඩනැගිලි සැලසුම් කිරීමේදී 'නිෂ්ක්‍රීය සිසිලනය' (Passive Cooling) යොදා ගන්නේ කෙසේද?",
        "හරස් වාතාශ්‍රය (Cross-ventilation), හිරු ආවරණ (Sunshades), ඉහළ වහල, පරාවර්තක වර්ණ හා අවට ගස් සෙවණ යොදා වායු සමීකරණ අවශ්‍යතාව අඩු කිරීම", "සියලු ජනෙල් වසා වායු සමීකරණ 10 ක් සවි කිරීම", "කළු වහල දැමීම", "වීදුරු පෙට්ටි තැනීම",
        "ශ්‍රී ලංකාවේ ජෙෆ්රි බාවාගේ නිවර්තන නූතනවාදී ගෘහ නිර්මාණ ශිල්පය ස්වාභාවික වාතාශ්‍රය හා ආලෝකය උපරිමයෙන් භාවිත කළේය."),
      q(t, "'ජෛව සම්පත් මංකොල්ලය' (Biopiracy) යන සංකල්පය නිවර්තන ජෛව විවිධත්වයෙන් පොහොසත් රටවලට අදාළ වන්නේ කෙසේද?",
        "විදේශීය සමාගම් දේශීය ප්‍රජාවගේ අවසරයකින් හෝ ප්‍රතිලාභ බෙදා ගැනීමකින් තොරව ආවේණික ඖෂධීය ශාක හා සාම්ප්‍රදායික දැනුම භාවිත කර පේටන්ට් බලපත්‍ර ලබා ලාභ ඉපැයීම", "වනාන්තරවල ගස් ගණන් කිරීම", "පැළ සිටුවීම", "ජාතික උද්‍යාන නැරඹීම",
        "නගෝයා සන්ධානය (Nagoya Protocol) ජානමය සම්පත් භාවිතයෙන් ලැබෙන ප්‍රතිලාභ මව් රට සමඟ සාධාරණව බෙදා ගැනීම (ABS) තහවුරු කරයි."),
      q(t, "'ශ්‍රී ලංකාවේ බහුල පැලෑටි හා කෘෂි අපද්‍රව්‍යයක් වන කොහුබත්, දහයියා හා ග්ලිරිසීඩියා (වැටමාර)' බලශක්ති හා පොහොර සම්පතක් ලෙස යොදා ගන්නේ කෙසේද?",
        "ඩෙන්ඩ්‍රෝ තාප විදුලි බලාගාරවල (Dendro Power) ඉන්ධන ලෙස විදුලිය නිපදවීමටත්, කොහුබත් අපනයන පැළ තවාන් මාධ්‍ය ලෙසත් භාවිත කිරීම", "මුහුදට දැමීමට පමණි", "රසායනික පොහොර සෑදීමට පමණි", "වාහන ධාවනයට පමණි",
        "ගොවීන් වැටමාර ගස් වගා කර දැව සැපයීමෙන් ග්‍රාමීය අමතර ආදායමක් උපයා ගැනීමට ඩෙන්ඩ්‍රෝ බලශක්ති ව්‍යාපෘති උපකාරී වේ."),
      q(t, "'විදුලි බලශක්ති සංචිතකරණයට' අමතරව 'තාප ගබඩා හා සුළං ටර්බයින ප්‍රතිචක්‍රීකරණය' නව අභියෝගයක් වී ඇත්තේ ඇයි?",
        "වසර 20–25 ක ආයු කාලය අවසන් වන විශාල ෆයිබර්ග්ලාස් සුළං ටර්බයින් තටු හා පැරණි සූර්ය පැනල අපද්‍රව්‍ය පරිසර හිතකාමීව ප්‍රතිචක්‍රීකරණය කිරීමට අවශ්‍ය වීම", "ඒවා වතුරේ දියවන නිසා", "ඒවා දැව වලින් සාදා ඇති නිසා", "ඒවා සදාකාලික නිසා",
        "නව චක්‍රීය සැලසුම් මගින් ප්‍රතිචක්‍රීකරණය කළ හැකි තාප-ප්ලාස්ටික් ටර්බයින් තටු නිපදවීම දැන් ආරම්භ වී ඇත."),
      q(t, "'ගංගා නිම්නවල වගුරු හා පිටාර තැනිතලා' (Floodplains) ඉඩම් සම්පතක් ලෙස සංවර්ධනය කිරීමේදී අවධානය යොමු කළ යුත්තේ කුමන සීමාව කෙරෙහිද?",
        "වැසි සමයේදී ගංගාවේ අතිරික්ත ජලය රැඳී ගංවතුර පාලනය කරන ස්වාභාවික ප්‍රදේශ බැවින් ඒවා සම්පූර්ණයෙන් ගොඩකර නිවාස ඉදි නොකර කෘෂිකර්මය හෝ හරිත උද්‍යාන ලෙස තබා ගැනීම", "සම්පූර්ණයෙන් කොන්ක්‍රීට් කිරීම", "ගංගාව වැසීම", "රසායනික කම්හල් තැනීම",
        "පිටාර තැනිතලා වගා බිම්වලට නිරන්තර ගංවතුරෙන් සාරවත් දියළු රොන්මඩ ලැබෙන නිසා ඒවා ඉහළ සාරවත්භාවයකින් යුක්තය."),
      q(t, "'ජල පරිභෝජනය හා කෘෂිකර්මයේ සුරක්ෂිතතාව' සඳහා 'කුඩා වාරි වැව් ප්‍රතිසංස්කරණය' ශ්‍රී ලංකාවේ ජාතික ප්‍රමුඛතාවක් වන්නේ ඇයි?",
        "රොන්මඩ ඉවත් කර වැව් බැමි හා සොරොව් ප්‍රතිසංස්කරණය කිරීමෙන් වැසි ජලය වැඩි ප්‍රමාණයක් ගබඩා කර මහ හා යල කන්න දෙකේම අස්වැන්න තහවුරු කළ හැකි බැවින්", "වැව් වසා ගෙවල් සෑදීමට", "වැව් මුහුදට හැරවීමට", "මසුන් ඉවත් කිරීමට",
        "ශ්‍රී ලංකාවේ කුඩා හා මධ්‍ය පරිමාණ වැව් 15,000 කට අධික සංඛ්‍යාවක් ග්‍රාමීය ජල හා ආහාර සුරක්ෂිතතාවයේ කොඳු නාරටිය වේ."),
      q(t, "'ලෝක සාගර දිනය' සහ 'ලෝක ජල දිනය' වැනි ජාත්‍යන්තර දින ප්‍රකාශයට පත් කර ඇත්තේ කුමන අරමුණින්ද? (මාර්තු 22 - ලෝක ජල දිනය)",
        "මිරිදිය සම්පතේ වටිනාකම, ජල අර්බුදය පිළිබඳ ගෝලීය අවධානය යොමු කිරීම සහ තිරසාර ජල කළමනාකරණය සඳහා ක්‍රියාමාර්ග දිරිමත් කිරීම", "ජලය නාස්ති කිරීම සැමරීමට", "සාගරයට ප්ලාස්ටික් දැමීමට", "වැව් වියළීමට",
        "ජල සංරක්ෂණය සෑම පුරවැසියෙකුගේම, කර්මාන්තයකම හා රජයකම පොදු වගකීමකි."),
      q(t, "'ගෝලීය බලශක්ති පරිභෝජන අසමානතාව' (Energy Poverty vs High Consumption) නිවැරදිව විස්තර කරන්නේ කුමක්ද?",
        "සංවර්ධිත රටවල ඒක පුද්ගල බලශක්ති පරිභෝජනය අතිශයින් ඉහළ මට්ටමක පවතින අතර උප-සහරා අප්‍රිකාවේ හා දුරස්ථ ග්‍රාමීය පෙදෙස්වල මිලියන සිය ගණනකට තවමත් විදුලිය නොමැති වීම", "සෑම රටකම විදුලි පරිභෝජනය සමාන වීම", "අප්‍රිකාවේ විදුලි පරිභෝජනය ඇමරිකාවට වඩා වැඩි වීම", "ලොව කිසිවෙකු විදුලිය භාවිත නොකිරීම",
        "විමධ්‍යගත සූර්ය ක්ෂුද්‍ර ජාල (Solar Microgrids) මගින් දුරස්ථ ගම්මානවලට අඩු වියදමින් විදුලිය ලබා දිය හැකිය."),
      q(t, "'ඛනිජ හා ඉන්ධන සම්පත්වල භූ-දේශපාලනය' (Resource Geopolitics) අනුව නූතන ලෝකයේ රටවල් 'ලිතියම් හා දුර්ලභ පස් සැපයුම්' සඳහා උනන්දු වන්නේ ඇයි?",
        "බැටරි, සූර්ය/සුළං බලශක්ති උපාංග, විදුලි වාහන, 5G ජාල හා ආරක්ෂක තාක්ෂණය පූර්ණ වශයෙන් මෙම ඛනිජ මත රඳා පවතින බැවින්", "ඒවා ගඩොල් සෑදීමට භාවිත කරන බැවින්", "ඒවා ආහාර වර්ග බැවින්", "ඒවායින් ගල් අඟුරු හදන බැවින්",
        "ඛනිජ තෙල් යුගයේ සිට 'විවේචනාත්මක හරිත ඛනිජ' (Critical Minerals) යුගය වෙත ගෝලීය බලශක්ති ආර්ථිකය මාරු වෙමින් පවතී."),
      q(t, "'ශ්‍රී ලංකාවේ බලශක්ති ප්‍රතිපත්තියේ' 2030 ඉලක්කය ලෙස රජය විසින් හඳුන්වා දී ඇති ප්‍රධාන හරිත අරමුණ කුමක්ද?",
        "රටේ මුළු විදුලි ජනනයෙන් 70% කට ආසන්න ප්‍රමාණයක් සූර්ය, සුළං, ජල හා ජෛව ස්කන්ධ වැනි පුනර්ජනනීය ප්‍රභවයන්ගෙන් ලබා ගැනීම", "100% ගල් අඟුරු පමණක් භාවිත කිරීම", "සියලු ජල විදුලි බලාගාර වැසීම", "සූර්ය පැනල තහනම් කිරීම",
        "මේ සඳහා ජාතික විදුලි සම්ප්‍රේෂණ ජාලය නවීකරණය කිරීම හා බලශක්ති ගබඩා පහසුකම් වැඩි කිරීම අත්‍යවශ්‍ය වේ."),
      q(t, "'ඛනිජ ජලය හා භූගත ජල සම්පත' වාණිජමය වශයෙන් අධිකව පොම්ප කිරීමේදී ඇතිවන 'භූමිය ගිලා බැසීම' (Land Subsidence) වාර්තා වී ඇති ප්‍රධාන නගර මොනවාද?",
        "මෙක්සිකෝ සිටි, බැංකොක්, ජකර්තා සහ ෂැංහයි (භූගත අවසාදිත ස්තරවල ජල පීඩනය අඩු වීමෙන් පස සංකෝචනය වී ගිලා බැසීම)", "මහනුවර සහ නුවරඑළිය", "කැන්බරා සහ සූරිච්", "ලහාසා සහ කත්මණ්ඩු",
        "නගර ගිලා බැසීම සහ මුහුදු මට්ටම ඉහළ යාම එකතු වූ විට වෙරළබඩ ගංවතුර අවදානම දෙගුණ වේ."),
      q(t, "'ස්වාභාවික භූමි සම්පත් ආරක්ෂා කිරීමේදී' රජය විසින් සිදු කරන 'භූමි පරිභෝජන සැලසුම්කරණය' (Land Use Zoning) මගින් සිදුවන කාර්යය කුමක්ද?",
        "සාරවත් කෘෂි ඉඩම්, ජල පෝෂක, වන රක්ෂිත, නේවාසික පෙදෙස් හා කාර්මික කලාප සුදුසු ස්ථානවලට වෙන් කර ගැටුම් හා පාරිසරික විනාශය වැළැක්වීම", "සෑම තැනකම කර්මාන්තශාලා තැනීම", "වනාන්තර මැද නගර සෑදීම", "කුඹුරු සියල්ල ගොඩකිරීම",
        "නිවැරදි කලාපකරණය (Zoning) ආපදා අවදානම අඩු කිරීමටත්, සම්පත් තිරසාරව භාවිත කිරීමටත් මග පාදයි."),
      q(t, "'තිරසාර ධීවර කළමනාකරණයේදී' 'දැල් ඇස් ප්‍රමාණය නියාමනය කිරීම' (Mesh Size Regulation) අත්‍යවශ්‍ය වන්නේ ඇයි?",
        "කුඩා පැටවුන් හා පරිණත නොවූ මසුන් දැලට හසු නොවී බේරී යාමට ඉඩ හැර, මත්ස්‍ය ගහනය නැවත බෝ වීම සහතික කිරීමට", "සියලු කුඩා මසුන් ඇල්ලීමට", "දැල් සම්පූර්ණයෙන් ඉරා දැමීමට", "මුහුදේ ප්ලාස්ටික් එකතු කිරීමට",
        "එසේම විෂ ද්‍රව්‍ය, ඩයිනමයිට් හා පතුල් ඇදගෙන යන තහනම් දැල් (Bottom Trawling) භාවිතය කොරල්පර හා මත්ස්‍ය වාසභූමි විනාශ කරයි."),
      q(t, "'ගංගා ඉවුරු හා වෙරළ තීරයන්' ස්වාභාවිකව ස්ථායී කිරීමට කොන්ක්‍රීට් බැමි වෙනුවට භාවිත කරන 'ජෛව ඉංජිනේරු ක්‍රම' (Bio-engineering) මොනවාද?",
        "වැටකෙයියා, මුහුදු බිම්තඹුරු, කඩොලාන, කුඹුක් හා උණ පඳුරු සිටුවා ශාක මුල් ජාලයෙන් පස බැඳ තැබීම", "වෙරළට ප්ලාස්ටික් අතුරා තැබීම", "ගස් සියල්ල ගලවා දැමීම", "රසායනික තෙල් ඉසීම",
        "ජෛව ඉංජිනේරු ක්‍රම ලාභදායී වන අතරම පරිසර පද්ධතියට සෙවණ හා වාසභූමිද නිර්මාණය කරයි."),
      q(t, "'විදුලි වාහන ආරෝපණ ජාල හා පොදු විදුලි බස් රථ' බලශක්ති සම්පත් භූගෝල විද්‍යාවේ වැදගත් වෙනසක් සිදු කරන්නේ කෙසේද?",
        "විශාල නාගරික වායු දූෂණය හා ආනයනික පෙට්‍රල්-ඩීසල් බිල අඩු කර රටේ දේශීයව නිපදවන හරිත විදුලියෙන් ප්‍රවාහනය ක්‍රියාත්මක කිරීමට හැකි වීම", "තෙල් පරිභෝජනය වැඩි කිරීම", "නගරවල ශබ්දය වැඩි කිරීම", "දුමාරය වැඩි කිරීම",
        "ලෝකයේ සමහර රටවල් (උදා: නෝර්වේ) අලෙවි වන නව මෝටර් රථවලින් 80%–90% කට වඩා දැනටමත් විදුලි වාහන බවට පත් කර ඇත."),
      q(t, "'ජල පෝෂක සේවා ගෙවීම්' (Payments for Ecosystem Services - PES) යන නව සම්පත් කළමනාකරණ ක්‍රමය යටතේ සිදුවන්නේ කුමක්ද?",
        "පහළ නගරයේ ජල පරිභෝගිකයන් හෝ විදුලි බලාගාර ඉහළ කඳුකරයේ ගොවීන්ට වනාන්තර ආරක්ෂා කිරීම හා පාංශු ඛාදනය වැළැක්වීම වෙනුවෙන් මූල්‍ය ප්‍රතිලාභ ගෙවීම", "වනාන්තර කපන අයට තෑගි දීම", "ජලය දූෂණය කිරීමට මුදල් දීම", "කඳුකර ගොවීන් ඉවත් කිරීම",
        "කොස්ටාරිකාව සහ නිව්යෝක් නගරය මෙම PES ක්‍රමයෙන් පිරිසිදු ජල සැපයුම අඩු වියදමකින් රැකගත් ලෝක ප්‍රසිද්ධ උදාහරණ වේ."),
      q(t, "'වැවිලි බෝග' අතර ශ්‍රී ලංකාවේ 'තේ, රබර්, පොල් සහ කුරුඳු' වලට අමතරව 'ලුණු හා මිනිරන්' සම්පත්වල පවතින ස්වාභාවික වෙනස කුමක්ද?",
        "තේ, රබර්, පොල් හා කුරුඳු පුනර්ජනනීය ජෛව/කෘෂි සම්පත් වන අතර ලුණු සූර්ය වාෂ්පීභවනයෙන් නිරන්තරයෙන් සාගරයෙන් ලැබෙන අතර මිනිරන් ක්ෂය වන භූගත ඛනිජ සම්පතකි", "සියල්ල ගස්වල වැඩේ", "සියල්ල පොළොව යට පතල්වලින් ගනී", "ලුණු ක්ෂය වන ඛනිජයකි",
        "එබැවින් මිනිරන් වැනි ක්ෂය වන සම්පත් අමුද්‍රව්‍ය ලෙස නොව ග්‍රැෆීන් (Graphene) හා බැටරි ඇනෝඩ ලෙස ඉහළ අගයක් එකතු කර අපනයනය කිරීම වඩාත් ඵලදායී වේ."),
      q(t, "'නාගරික හා ග්‍රාමීය ජල බෙදාහැරීමේදී' ජල මීටර් සවි කිරීම හා ස්ථරගත ජල ගාස්තු ක්‍රමය (Block Tariff) ක්‍රියාත්මක කිරීමේ ප්‍රධාන අරමුණ කුමක්ද?",
        "මූලික අත්‍යවශ්‍ය ජල ප්‍රමාණය සඳහා සියලු දෙනාටම දැරිය හැකි අඩු මිලක් අය කර අධික නාස්තිකාර පරිභෝජනය සඳහා ඉහළ ගාස්තු අය කර ජලය සංරක්ෂණය කිරීම", "දුප්පත් අයට ජලය නොදීම", "වැඩිපුර ජලය නාස්ති කිරීමට පෙළඹවීම", "වැසි නතර කිරීම",
        "මෙමගින් සමාජ සාධාරණත්වයත් සම්පත් සංරක්ෂණයත් යන දෙකම ඉටු වේ."),
      q(t, "'ද්වි-මාර්ග පාරිසරික හා බලශක්ති කළමනාකරණයේදී' 'හරිත ගිණුම්කරණය' (Green Accounting / Natural Capital Accounting) වැදගත් වන්නේ ඇයි?",
        "රටක ජාතික ආදායම (GDP) ගණනය කිරීමේදී කාර්මික ලාභය පමණක් නොව වන විනාශය, ඛනිජ ක්ෂය වීම හා ජල දූෂණයෙන් සිදුවන පාරිසරික පිරිවැයද සැලකිල්ලට ගන්නා බැවින්", "මුදල් නෝට්ටු කොළ පාට කිරීම නිසා", "ගස් කැපීම ආදායමක් ලෙස පමණක් ගන්නා නිසා", "පරිසරය නොසලකා හරින නිසා",
        "සැබෑ තිරසාර සංවර්ධනයක් සඳහා ස්වාභාවික ප්‍රාග්ධනය (Natural Capital) රැක ගැනීම අත්‍යවශ්‍ය වේ."),
      q(t, "අවසාන වශයෙන්, ගෝලීය සම්පත් අර්බුදය විසඳීම සඳහා 'කාර්යක්ෂමතාව, ප්‍රතිචක්‍රීකරණය හා පුනර්ජනනීය බලශක්තිය' සමඟ අත්‍යවශ්‍ය වන මානව චර්යාත්මක වෙනස කුමක්ද?",
        "අති-පරිභෝජනවාදය (Overconsumption) හා ආහාර/භාණ්ඩ නාස්තිය අඩු කර සරල, වගකීම්සහගත හා තිරසාර ජීවන රටාවකට (SDG 12) යොමු වීම", "සෑම මසකම නව උපකරණ මිලදී ගෙන පැරණි ඒවා විසි කිරීම", "වැඩිපුර ප්ලාස්ටික් භාවිතය", "ජලය අරපිරිමැස්මෙන් තොරව හැර දැමීම",
        "තාක්ෂණය පමණක් නොව සම්පත්වල සීමිත බව අවබෝධ කරගත් වගකීම්සහගත පුරවැසි පරිභෝජනයද තිරසාර අනාගතයට අත්‍යවශ්‍ය වේ."),
      q(t, "'ජල පියසටහන' (Water Footprint) යන පාරිසරික දර්ශකයෙන් මනිනු ලබන්නේ කුමක්ද?",
        "පුද්ගලයෙකු, ප්‍රජාවක් හෝ භාණ්ඩයක් නිෂ්පාදනය කිරීම සඳහා සෘජුව හා වක්‍රව පරිභෝජනය වන සහ දූෂණය වන මුළු මිරිදිය පරිමාව", "සපත්තුවක දිග", "මුහුදු ජලයේ උෂ්ණත්වය", "වර්ෂාවේ වේගය",
        "කිලෝග්‍රෑම් 1 ක හරක් මස් හෝ කපු ඇඳුමක් නිපදවීමට පිටුපසින් ලීටර් දහස් ගණනක 'අතථ්‍ය ජලය' (Virtual Water) වැය වේ."),
      q(t, "'හරිත ජලය, නිල් ජලය හා අළු ජලය' (Green, Blue, Grey Water) යන ජල පියසටහන් කාණ්ඩ අතර 'නිල් ජලය' (Blue Water) යනු කුමක්ද?",
        "භූගත ජලධර, ගංගා, වැව් හා ජලාශවලින් කෘෂිකර්මය, කර්මාන්ත හා ගෘහස්ථ අවශ්‍යතා සඳහා පොම්ප කර හෝ ඇළ මාර්ග හරහා ලබා ගන්නා මිරිදිය ජලය", "වලාකුළු වල ඇති ජලය", "සාගර ලුණු ජලය", "අපජලය",
        "හරිත ජලය යනු පසෙහි රැඳෙන වැසි ජලය වන අතර අළු ජලය යනු දූෂක තනුක කිරීමට අවශ්‍ය ජල ප්‍රමාණයයි."),
      q(t, "'ඛනිජ වැලි සම්පත්' අතර ශ්‍රී ලංකාවේ පුල්මුඩේ වෙරළ තීරයේ බහුලව හමුවන ඉල්මනයිට් (Ilmenite), රූටයිල් (Rutile) හා සර්කෝන් (Zircon) ඛනිජ කර්මාන්තයේදී භාවිත වන්නේ කුමක් සඳහාද?",
        "තීන්ත වර්ණක, ගුවන් යානා/වෛද්‍ය උපකරණ සඳහා ටයිටේනියම් ලෝහය, සෙරමික් ඔප දැමීම හා පරමාණුක ඉංජිනේරු යෙදවුම් සඳහා", "ගල් අඟුරු පිළිස්සීමට", "රබර් කිරි කැපීමට", "ලුණු සෑදීමට",
        "ඉහළ ටයිටේනියම් සංශුද්ධතාවයක් ඇති පුල්මුඩේ ඛනිජ වැලි නිධිය ලොව ඉතා වටිනා වෙරළබඩ ඛනිජ සම්පතකි."),
      q(t, "'එප්පාවල රොක් පොස්පේට් නිධිය' (Eppawala Rock Phosphate) ශ්‍රී ලංකාවේ කෘෂිකර්මයට වැදගත් සම්පතක් වන්නේ ඇයි?",
        "කෘෂි බෝගවල මුල් වර්ධනයට හා අස්වැන්නට අත්‍යවශ්‍ය පොස්පරස් පෝෂකය සපයන දේශීය පොහොර අමුද්‍රව්‍යයක් (Heron Rock Phosphate) ලෙස විදේශ විනිමය ඉතිරි කරන බැවින්", "එයින් විදුලිය නිපදවන නිසා", "ගොඩනැගිලි වීදුරු හදන නිසා", "රන් වෙන් කරන නිසා",
        "තිරසාර කැණීම් හා දියවන තනි සුපර් පොස්පේට් (SSP) බවට පත් කිරීමෙන් දීර්ඝකාලීන ප්‍රතිලාභ ලබාගත හැකිය."),
      q(t, "'අපේ රටේ තෙල් පිරිපහදුව හා උපායමාර්ගික තෙල් ටැංකි සංකීර්ණය' පිහිටි ස්ථාන දෙක පිළිවෙළින් මොනවාද?",
        "සපුගස්කන්ද තෙල් පිරිපහදුව සහ ත්‍රිකුණාමලය චීන වරාය තෙල් ටැංකි සංකීර්ණය", "නුවරඑළිය සහ බදුල්ල", "යාපනය සහ වව්නියාව", "රත්නපුර සහ මහනුවර",
        "ත්‍රිකුණාමලය ස්වාභාවික ගැඹුරු වරාය ආශ්‍රිතව පිහිටි තෙල් ටැංකි සංකීර්ණය කලාපීය බලශක්ති කේන්ද්‍රයක් ලෙස විශාල විභවයක් දරයි."),
      q(t, "'ලිතියම්, කොබෝල්ට් හා දුර්ලභ පස් මූලද්‍රව්‍ය' (Critical Minerals - REE) 21 වන සියවසේ 'නව තෙල්' ලෙස හඳුන්වන්නේ ඇයි?",
        "විදුලි වාහන බැටරි, සූර්ය පැනල, සුළං ටර්බයින චුම්භක, ස්මාර්ට්ෆෝන් හා චන්ද්‍රිකා නිෂ්පාදනය සඳහා ඒවා නැතිවම බැරි ඛනිජ වන බැවින්", "ඒවා ආහාරයට ගන්නා නිසා", "ඉන්ධන ලෙස පුළුස්සන නිසා", "ගඩොල් සෑදීමට ගන්නා නිසා",
        "චිලී, ඕස්ට්‍රේලියාව, චීනය හා කොංගෝ ප්‍රජාතන්ත්‍රවාදී ජනරජය මෙම තීරණාත්මක ඛනිජ සැපයුමේ ප්‍රධාන රටවල් වේ."),
      q(t, "'භූගත ගෑස් ව්‍යුහය හා මන්නාරම් ද්‍රෝණිය' (Mannar Basin) ශ්‍රී ලංකාවේ බලශක්ති ගවේෂණයේදී සඳහන් වන්නේ ඇයි?",
        "භූ කම්පන සමීක්ෂණ හා ගවේෂණ කැණීම් මගින් මන්නාරම් ද්‍රෝණියේ මුහුදු පතුල යට ස්වාභාවික වායු හා ඛනිජ තෙල් විභවයක් පවතින බව හඳුනාගෙන ඇති බැවින්", "එහි විශාල කඳු වැටියක් ඇති නිසා", "ගල් අඟුරු පතලක් විවෘත කර ඇති නිසා", "මිරිදිය ගංගාවක් ගලන නිසා",
        "සාගර පරිසර ආරක්ෂාව සමඟ සැලසුම් සහගත බලශක්ති ගවේෂණය බලශක්ති සුරක්ෂිතතාවට වැදගත් වේ."),
      q(t, "'ජල විදුලි බලාගාර හා තාප විදුලි බලාගාර' අතර ශ්‍රී ලංකාවේ 'මහවැලි සංකීර්ණය' (කොත්මලේ, වික්ටෝරියා, රන්දෙණිගල, රන්ටැඹේ) ඉටු කරන ද්විත්ව මෙහෙවර කුමක්ද?",
        "පුනර්ජනනීය ජල විදුලිය උත්පාදනය කිරීමට අමතරව වියළි කලාපයේ හෙක්ටයාර ලක්ෂ ගණනකට වසර පුරා වාරි ජලය හා පානීය ජලය සැපයීම", "මුහුදු ජලය ලුණු බවට පත් කිරීම", "ගල් අඟුරු කැණීම", "සුළං වේගය අඩු කිරීම",
        "බහුකාර්ය ජලාශ ව්‍යාපෘති ජල, ආහාර හා බලශක්ති සුරක්ෂිතතාව (Water-Energy-Food Nexus) එකවර සපුරාලයි."),
      q(t, "'කාබන් වෙන් කර ගබඩා කිරීම' (Carbon Capture and Storage - CCS) යන තාක්ෂණික ක්‍රියාවලියෙන් අදහස් කරන්නේ කුමක්ද?",
        "බලාගාර හා කර්මාන්තශාලාවලින් පිටවන කාබන් ඩයොක්සයිඩ් වායුගෝලයට මුදා හැරීමට පෙර අල්ලා ගෙන භූගත ගැඹුරු පාෂාණ ස්තර තුළ ආරක්ෂිතව තැන්පත් කිරීම", "වනාන්තර කපා දැමීම", "කාබන් වායුව නගර තුළට මුදා හැරීම", "පෙට්‍රල් භාවිතය වැඩි කිරීම",
        "කෙසේ වෙතත් CCS තාක්ෂණය ඉතා මිල අධික බැවින් පළමුව පොසිල ඉන්ධන භාවිතය අඩු කිරීම වඩා ප්‍රමුඛ වේ."),
      q(t, "'වෘත්තීය හා ගෘහස්ථ හරිත හයිඩ්‍රජන්' (Green Hydrogen) අනාගත බලශක්ති සම්පතක් ලෙස ඉස්මතු වී ඇත්තේ ඇයි?",
        "සූර්ය හෝ සුළං විදුලිය යොදා ජලය විද්‍යුත් විච්ඡේදනය කිරීමෙන් (Electrolysis) නිපදවන බැවින් දහනයේදී කාබන් විමෝචනයකින් තොරව ජල වාෂ්ප පමණක් පිටවීම", "එය ගල් අඟුරුවලින් හදන නිසා", "දහනයේදී අධික දුම් පිටවන නිසා", "කාන්තාර වැලිවලින් හදන නිසා",
        "වානේ කර්මාන්තය, නැව් හා බර ප්‍රවාහනය කාබන්හරණය කිරීමට හරිත හයිඩ්‍රජන් විශාල බලාපොරොත්තුවකි."),
      q(t, "'ජල පෝෂක ප්‍රදේශවල අනවසර මැණික් ගැරීම හා වැලි ගොඩදැමීම' මගින් ජල හා පස් සම්පත්වලට සිදුවන බරපතලම හානිය කුමක්ද?",
        "ගංගා ඉවුරු කඩා වැටීම, ජලය මඩ වීම, භූගත ජල මට්ටම පහළ බැස පානීය ජල ළිං සිඳී යාම සහ ගංගා මෝයට ලවණ ජලය ඇතුළු වීම", "ජලය වඩාත් පිරිසිදු වීම", "මසුන් ගහනය දෙගුණ වීම", "පාංශු සාරවත් බව වැඩි වීම",
        "කැලණි, කළු, නිල්වලා, දැදුරු ඔය හා මහ ඔය නිම්නවල අධික වැලි ගොඩදැමීම පාලම් හා ජල පවිත්‍රාගාරවලටද තර්ජනයකි."),
      q(t, "'ජීව-විවිධත්ව උණුසුම් කලාපයක්' (Biodiversity Hotspot) ලෙස 'ශ්‍රී ලංකාව සහ බටහිර ඝාට් කලාපය' හඳුන්වනු ලබන්නේ ඇයි?",
        "විශාල ආවේණික ශාක හා සත්ත්ව විශේෂ ප්‍රමාණයක් (Endemic species) ජීවත් වන අතරම මානව ක්‍රියාකාරකම් නිසා එම වාසභූමිවලින් 70% කට වඩා තර්ජනයට ලක්ව ඇති බැවින්", "එහි වායු උෂ්ණත්වය 100°C වන නිසා", "ශාක විශේෂ කිසිවක් නොමැති නිසා", "කාන්තාරයක් වන නිසා",
        "සිංහරාජය, කන්නෙලිය, නකල්ස් හා හෝර්ටන් තැන්න ආරක්ෂා කිරීම මෙම ගෝලීය උරුමය රැක ගැනීමට අත්‍යවශ්‍ය වේ."),
      q(t, "'සමුද්‍ර ආරක්ෂිත කලාප' (Marine Protected Areas - MPA, උදා: පරෙවි දූපත, හික්කඩුව, බාර් රීෆ්) ස්ථාපිත කිරීමෙන් ධීවර සම්පතට ලැබෙන වාසිය කුමක්ද?",
        "මසුන්ට ආරක්ෂිතව බෝ වීමට හා වැඩීමට අභයභූමියක් සැලසී, ඉන් පිටත අවට ධීවර කලාපවලටද මසුන් ගලා යාම (Spillover Effect) වැඩි වීම", "සියලු මසුන් අතුරුදහන් වීම", "කොරල් පර විනාශ වීම", "ධීවර අස්වැන්න සදහටම අවසන් වීම",
        "තිරසාර ධීවර කළමනාකරණය සඳහා 'No-take' සාගර කලාප විද්‍යාත්මකව සාර්ථක බව තහවුරු වී ඇත."),
      q(t, "'වැසි ජලය රැස් කිරීම' (Rainwater Harvesting) ගෘහස්ථ හා කෘෂිකාර්මික ජල කළමනාකරණයේදී වියළි කලාපයට වැදගත් වන්නේ ඇයි?",
        "ඊසානදිග මෝසමෙන් ලැබෙන කෙටි කාලීන අධික වැසි ජලය වහලවල් හා කුඩා පොකුණු තුළ ගබඩා කර වියළි මාසවලදී පානීය හා ගෙවතු වගා අවශ්‍යතා සඳහා භාවිත කළ හැකි බැවින්", "ලුණු ජලය ලබා ගැනීමට", "වැසි ජලය කෙලින්ම මුහුදට යැවීමට", "භූගත ජලය අපවිත්‍ර කිරීමට",
        "ශ්‍රී ලංකාවේ නාගරික ගොඩනැගිලි සැලසුම් නීති යටතේද විශාල ගොඩනැගිලිවල වැසි ජල රැස් කිරීමේ පද්ධති දිරිමත් කෙරේ."),
      q(t, "'කාබනික ද්‍රව්‍ය හා කොම්පෝස්ට්' පසට එකතු කිරීම පාංශු සම්පත් සංරක්ෂණයේදී තීරණාත්මක වන්නේ ඇයි?",
        "පසේ ජලය රඳවා ගැනීමේ ධාරිතාව වැඩි කර, ක්ෂුද්‍ර ජීවී ක්‍රියාකාරිත්වය වර්ධනය කර, රසායනික පොහොර සේදී යාම හා පස දැඩි වීම වළක්වන බැවින්", "පස නිසරු කිරීමට", "ගැඩවිලුන් විනාශ කිරීමට", "ජලය ගලා යාම වැඩි කිරීමට",
        "නිරෝගී සාරවත් පසක් සෙන්ටිමීටර කිහිපයක් ස්වාභාවිකව සෑදීමට වසර සිය ගණනක් ගත වේ."),
      q(t, "'විදුලි පද්ධතිවල පූර්වගාමී පොම්පාගාර' (Pumped-Storage Hydroelectricity) පුනර්ජනනීය බලශක්ති ජාලයකට උපකාරී වන්නේ කෙසේද?",
        "දහවල් කාලයේ අතිරික්ත සූර්ය හෝ සුළං විදුලිය යොදා පහළ ජලාශයෙන් ඉහළ ජලාශයට ජලය පොම්ප කර, රාත්‍රී කාලයේ විදුලි ඉල්ලුම වැඩි වූ විට එම ජලය පහළට හෙළා විදුලිය නිපදවීමෙන්", "ගල් අඟුරු පිළිස්සීමෙන්", "ජලය වාෂ්ප කිරීමෙන්", "විදුලිය නාස්ති කිරීමෙන්",
        "මෙය ලෝකයේ විශාලතම 'ජල බැටරි' (Water Battery) බලශක්ති ගබඩා තාක්ෂණයයි (උදා: මහඔය ව්‍යාපෘති සංකල්ප)."),
      q(t, "'ලෝකයේ ප්‍රධාන යකඩ ලෝපස් (Iron Ore) නිපදවන රටවල්' අතර ප්‍රමුඛ ස්ථාන ගන්නා රටවල් මොනවාද?",
        "ඕස්ට්‍රේලියාව (Pilbara කලාපය), බ්‍රසීලය (Carajás), චීනය සහ ඉන්දියාව", "ස්විට්සර්ලන්තය, නෝර්වේ සහ මාලදිවයින", "ජපානය, සිංගප්පූරුව සහ කුවේට්", "අයිස්ලන්තය, ඊජිප්තුව සහ කෙන්යාව",
        "විශේෂයෙන් ඕස්ට්‍රේලියාව හා බ්‍රසීලය ලොව ප්‍රධානතම උසස් තත්ත්වයේ යකඩ ලෝපස් අපනයනකරුවන් වේ."),
      q(t, "'බොක්සයිට්' (Bauxite) යන ඛනිජ සම්පතෙන් නිස්සාරණය කර ගන්නා හා ගුවන් යානා, ඇසුරුම් හා විදුලි රැහැන්වල බහුලව භාවිත වන සැහැල්ලු ලෝහය කුමක්ද?",
        "ඇලුමිනියම් (Aluminium)", "ඊයම් (Lead)", "රසදිය (Mercury)", "රත්තරන් (Gold)",
        "ගිනියා, ඕස්ට්‍රේලියාව, වියට්නාමය හා චීනය ලොව ප්‍රධාන බොක්සයිට් නිධි හිමි රටවල් වේ."),
      q(t, "'ප්ලාස්ටික් හා පොලිතින් ප්‍රතිචක්‍රීකරණය සඳහා විස්තීරණ නිෂ්පාදක වගකීම' (EPR - Extended Producer Responsibility) යනු කුමක්ද?",
        "බෝතල් හා ඇසුරුම් නිපදවන සමාගම් තම නිෂ්පාදන පාරිභෝගිකයා විසින් ඉවත දැමූ පසු ඒවා එකතු කර ප්‍රතිචක්‍රීකරණය කිරීමේ නීතිමය හා මූල්‍ය වගකීම භාර ගැනීම", "පාරිභෝගිකයාට දඬුවම් කිරීම", "ප්ලාස්ටික් සාගරයට දැමීම", "නිෂ්පාදකයා නිදහස් කිරීම",
        "EPR ප්‍රතිපත්ති අපද්‍රව්‍ය කළමනාකරණ බර නගර සභාවලින් නිෂ්පාදකයන් වෙත සාධාරණව බෙදා දෙයි."),
      q(t, "'තෘණ බිම් හා සත්ත්ව පාලන සම්පත්' සංරක්ෂණයේදී 'භ්‍රමණ තෘණ කැවීම' (Rotational Grazing) වැදගත් වන්නේ ඇයි?",
        "එකම තණබිමක අඛණ්ඩව ගවයන් හා බැටළුවන් දැමීමෙන් තෘණ මුල් විනාශ වී පාංශු ඛාදනය හා කාන්තාරීකරණය සිදුවීම වළක්වා තෘණ නැවත වැඩීමට කාලය ලබා දෙන බැවින්", "සතුන්ට ආහාර නොදීමට", "සියලු තණකොළ පුළුස්සා දැමීමට", "පස දැඩි කිරීමට",
        "තිරසාර තෘණ බිම් කළමනාකරණය පසෙහි කාබන් තැන්පත් කිරීමද වැඩි කරයි."),
      q(t, "'ශ්‍රී ලංකාවේ දළ වශයෙන් වැඩිම පිරිසිදු බලශක්ති විභවයක් ඇති මන්නාරම හා පුනරීන් ප්‍රදේශවල' ප්‍රධාන වශයෙන් ක්‍රියාත්මක කර ඇති පුනර්ජනනීය බලශක්ති ව්‍යාපෘති මොනවාද?",
        "මහා පරිමාණ සුළං විදුලි බලාගාර (Thambapavani වැනි සුළං උද්‍යාන) හා සූර්ය විදුලි උද්‍යාන", "භූ තාප බලාගාර", "ගල් අඟුරු පතල්", "න්‍යෂ්ටික බලාගාර",
        "උතුරු හා වයඹදිග වෙරළබඩ තීරය නිරිතදිග හා ඊසානදිග මෝසම් සුළං දෙකෙන්ම ශක්තිය ලැබීමට ඉතා සුදුසුය."),
      q(t, "'ජල සම්පත් ආරක්ෂා කිරීමේ ඒකාබද්ධ ගංගා ද්‍රෝණි කළමනාකරණය' (Integrated River Basin Management - IRBM) යනු කුමක්ද?",
        "ගංගාවේ මුදුන් ජල පෝෂකයේ සිට මෝය දක්වා මුළු ද්‍රෝණියම තනි පාරිසරික ඒකකයක් ලෙස සලකා වනාන්තර, කෘෂිකර්මය, නගර, කර්මාන්ත හා පළාත් පාලන ආයතන එක්ව ජලය කළමනාකරණය කිරීම", "ගංගාවේ එක් කෙළවරක් පමණක් බැලීම", "ගංගා වැසීම", "අපජලය ගඟට හැරවීම",
        "පරිපාලන දිස්ත්‍රික් සීමාවලින් ගංගා බෙදිය නොහැකි බැවින් ද්‍රෝණි මට්ටමේ සැලසුම් අත්‍යවශ්‍ය වේ."),
      q(t, "'කෘෂිකාර්මික පසෙහි ලවණීකරණය' (Soil Salinization) බොහෝ විට වියළි කලාපීය වාරි ඉඩම්වල ඇති වන්නේ කෙසේද?",
        "අධික වාෂ්පීභවනයක් ඇති වියළි ප්‍රදේශවල ජල බැස්ම (Drainage) නිසි පරිදි නොමැතිව අධික ලෙස වාරි ජලය යෙදීමෙන් භූගත ලුණු මතුපිට පසට ඇදී තැන්පත් වීම", "වැඩිපුර කොම්පෝස්ට් දැමීමෙන්", "වැසි වැඩි වීමෙන්", "ගස් සිටුවීමෙන්",
        "බිංදු ජල සම්පාදනය හා නිසි කාණු පද්ධති සැකසීම මගින් පස ලවණ වීම වළක්වා ගත හැකිය."),
      q(t, "'ස්වාභාවික වනාන්තර වෙනුවට තනි විශේෂ කෘත්‍රිම වන වගා' (Monoculture Plantations - උදා: පයිනස් හෝ යුකැලිප්ටස්) පමණක් සිටුවීමේ පාරිසරික ගැටලුව කුමක්ද?",
        "සාමාන්‍යයෙන් ස්වාභාවික මිශ්‍ර වනාන්තරවලට වඩා ජෛව විවිධත්වය ඉතා අඩු වීම, භූගත ජලය වැඩිපුර උරා ගැනීම සහ ලැව් ගිනි පැතිරීමේ අවදානම වැඩි වීම", "ඒවා ඉතා හොඳ වනජීවී වාසභූමි වීම", "කිසිදු ගින්නක් ඇති නොවීම", "ජල උල්පත් දස ගුණයකින් වැඩි වීම",
        "එබැවින් වර්තමානයේ පැරණි පයිනස් වගා ඉවත් කර දේශීය ශාක යොදා මිශ්‍ර වනාන්තර ප්‍රතිස්ථාපනය (Restoration) කිරීම සිදු කෙරේ."),
      q(t, "'ගෝලීය සම්පත් පරිභෝජන විෂමතාවය' (Global Resource Consumption Inequality) සම්බන්ධයෙන් පිළිගත් සත්‍යය කුමක්ද?",
        "ලෝක ජනගහනයෙන් සුළු ප්‍රතිශතයක් වන ඉහළ ආදායම් ලබන කාර්මික රටවල් ලෝකයේ මුළු බලශක්ති, ලෝහ හා භාණ්ඩ සම්පත්වලින් අතිවිශාල කොටසක් පරිභෝජනය කරන අතර අඩු ආදායම් රටවල් ඉතා සුළු ඒක පුද්ගල පරිභෝජනයක් සිදු කිරීම", "සියලුම රටවල් සමානව සම්පත් භාවිත කිරීම", "දිළිඳු රටවල් වැඩිපුරම තෙල් පිළිස්සීම", "කිසිදු රටක් සම්පත් භාවිත නොකිරීම",
        "තිරසාර ගෝලීය අනාගතයක් සඳහා ධනවත් රටවල පාරිසරික පියසටහන අඩු කිරීමත් දිළිඳු රටවලට පිරිසිදු තාක්ෂණය ලබා දීමත් අවශ්‍ය වේ.")
    )
  }
}
